const QUESTIONS = [{"num":1,"text":"A company purchased cyber insurance to address items listed on the risk register. Which of the following\nstrategies does this represent?","options":[["A","Accept"],["B","Transfer"],["C","Mitigate"],["D","Avoid"]],"correct":"B"},{"num":2,"text":"Which of the following is the most likely to be used to document risks, responsible parties, and thresholds?","options":[["A","Risk tolerance"],["B","Risk transfer"],["C","Risk register"],["D","Risk analysis"]],"correct":"C"},{"num":4,"text":"A systems administrator notices that the research and development department is not using the company\nVPN when accessing various company-related services and systems. Which of the following scenarios\ndescribes this activity?","options":[["A","Espionage"],["B","Data exfiltration"],["C","Nation-state attack"],["D","Shadow IT"]],"correct":"D"},{"num":5,"text":"Which of the following threat vectors is most commonly utilized by insider threat actors attempting data\nexfiltration?","options":[["A","Unidentified removable devices"],["B","Default network device credentials"],["C","Spear phishing emails"],["D","Impersonation of business units through typosquatting"]],"correct":"A"},{"num":6,"text":"Which of the following agreement types defines the time frame in which a vendor needs to respond?","options":[["A","SOW"],["B","SLA"],["C","MOA"],["D","MOU"]],"correct":"B"},{"num":7,"text":"Which of the following is a feature of a next-generation SIEM system?","options":[["A","Virus signatures"],["B","Automated response actions"],["C","Security agent deployment"],["D","Vulnerability scanning"]],"correct":"B"},{"num":8,"text":"To improve the security at a data center, a security administrator implements a CCTV system and posts\nseveral signs about the possibility of being filmed. Which of the following best describe these types of\ncontrols? (Choose two.)","options":[["A","Preventive"],["B","Deterrent"],["C","Corrective"],["D","Directive"],["E","Compensating"],["F","Detective"]],"correct":"BF"},{"num":9,"text":"Which of the following examples would be best mitigated by input sanitization?","options":[["A","<script>alert(\"Warning!\");</script>"],["B","nmap - 10.11.1.130"],["C","Email message: \"Click this link to get your free gift card.\""],["D","Browser message: \"Your connection is not private.\""]],"correct":"A"},{"num":10,"text":"An attacker posing as the Chief Executive Officer calls an employee and instructs the employee to buy gift\ncards. Which of the following techniques is the attacker using?","options":[["A","Smishing"],["B","Disinformation"],["C","Impersonating"],["D","Whaling"]],"correct":"C"},{"num":11,"text":"After conducting a vulnerability scan, a systems administrator notices that one of the identified\nvulnerabilities is not present on the systems that were scanned. Which of the following describes this\nexample?","options":[["A","False positive"],["B","False negative"],["C","True positive"],["D","True negative"]],"correct":"A"},{"num":12,"text":"A recent penetration test identified that an attacker could flood the MAC address table of network switches.\nWhich of the following would best mitigate this type of attack?","options":[["A","Load balancer"],["B","Port security"],["C","IPS"],["D","NGFW"]],"correct":"B"},{"num":13,"text":"A user would like to install software and features that are not available with a smartphone's default software.\nWhich of the following would allow the user to install unauthorized software and enable new features?","options":[["A","SQLi"],["B","Cross-site scripting"],["C","Jailbreaking"],["D","Side loading"]],"correct":"C"},{"num":14,"text":"Which of the following phases of an incident response involves generating reports?","options":[["A","Recovery"],["B","Preparation"],["C","Lessons learned"],["D","Containment"]],"correct":"C"},{"num":15,"text":"Which of the following methods would most likely be used to identify legacy systems?","options":[["A","Bug bounty program"],["B","Vulnerability scan"],["C","Package monitoring"],["D","Dynamic analysis"]],"correct":"B"},{"num":16,"text":"Employees located off-site must have access to company resources in order to complete their assigned\ntasks. These employees utilize a solution that allows remote access without interception concerns. Which of\nthe following best describes this solution?","options":[["A","Proxy server"],["B","NGFW"],["C","VPN"],["D","Security zone"]],"correct":"C"},{"num":17,"text":"A company allows customers to upload PDF documents to its public e-commerce website. Which of the\nfollowing would a security analyst most likely recommend?","options":[["A","Utilizing attack signatures in an IDS"],["B","Enabling malware detection through a UTM"],["C","Limiting the affected servers with a load balancer"],["D","Blocking command injections via a WAF"]],"correct":"B"},{"num":18,"text":"A security analyst developed a script to automate a trivial and repeatable task. Which of the following best\ndescribes the benefits of ensuring other team members understand how the script works?","options":[["A","To reduce implementation cost"],["B","To identify complexity"],["C","To remediate technical debt"],["D","To prevent a single point of failure"]],"correct":"D"},{"num":19,"text":"A company is decommissioning its physical servers and replacing them with an architecture that will reduce\nthe number of individual operating systems. Which of the following strategies should the company use to\nachieve this security requirement?","options":[["A","Microservices"],["B","Containerization"],["C","Virtualization"],["D","Infrastructure as code"]],"correct":"B"},{"num":20,"text":"An administrator needs to perform server hardening before deployment. Which of the following steps\nshould the administrator take? (Choose two.)","options":[["A","Disable default accounts."],["B","Add the server to the asset inventory."],["C","Remove unnecessary services."],["D","Document default passwords."],["E","Send server logs to the SIEM."],["F","Join the server to the corporate domain."]],"correct":"AC"},{"num":21,"text":"A Chief Information Security Officer would like to conduct frequent, detailed reviews of systems and\nprocedures to track compliance objectives. Which of the following will be the best method to achieve this\nobjective?","options":[["A","Third-party attestation"],["B","Penetration testing"],["C","Internal auditing"],["D","Vulnerability scans"]],"correct":"C"},{"num":22,"text":"Which of the following security concepts is accomplished with the installation of a RADIUS server?","options":[["A","CIA"],["B","AAA"],["C","ACL"],["D","PEM"]],"correct":"B"},{"num":23,"text":"After creating a contract for IT contractors, the human resources department changed several clauses. The\ncontract has gone through three revisions. Which of the following processes should the human resources\ndepartment follow to track revisions?","options":[["A","Version validation"],["B","Version changes"],["C","Version updates"],["D","Version control"]],"correct":"D"},{"num":24,"text":"The executive management team is mandating the company develop a disaster recovery plan. The cost\nmust be kept to a minimum, and the money to fund additional internet connections is not available. Which\nof the following would be the best option?","options":[["A","Hot site"],["B","Cold site"],["C","Failover site"],["D","Warm site"]],"correct":"B"},{"num":25,"text":"An administrator at a small business notices an increase in support calls from employees who receive a\nblocked page message after trying to navigate to a spoofed website. Which of the following should the\nadministrator do?","options":[["A","Deploy multifactor authentication."],["B","Decrease the level of the web filter settings."],["C","Implement security awareness training."],["D","Update the acceptable use policy."]],"correct":"C"},{"num":26,"text":"Which of the following teams is best suited to determine whether a company has systems that can be\nexploited by a potential, identified vulnerability?","options":[["A","Purple team"],["B","Blue team"],["C","Red team"],["D","White team"]],"correct":"C"},{"num":27,"text":"A company is reviewing options to enforce user logins after several account takeovers. The following\nconditions must be met as part of the solution:\nAllow employees to work remotely or from assigned offices around the world.\nProvide a seamless login experience.\nLimit the amount of equipment required.\nWhich of the following best meets these conditions?","options":[["A","Trusted devices"],["B","Geotagging"],["C","Smart cards"],["D","Time-based logins"]],"correct":"A"},{"num":28,"text":"Which of the following methods can be used to detect attackers who have successfully infiltrated a\nnetwork? (Choose two.)","options":[["A","Tokenization"],["B","CI/CD"],["C","Honeypots"],["D","Threat modeling"],["E","DNS sinkhole"],["F","Data obfuscation"]],"correct":"CE"},{"num":29,"text":"A company wants to ensure that the software it develops will not be tampered with after the final version is\ncompleted. Which of the following should the company most likely use?","options":[["A","Hashing"],["B","Encryption"],["C","Baselines"],["D","Tokenization"]],"correct":"A"},{"num":30,"text":"An organization completed a project to deploy SSO across all business applications last year. Recently, the\nfinance department selected a new cloud-based accounting software vendor. Which of the following should\nmost likely be configured during the new software deployment?","options":[["A","RADIUS"],["B","SAML"],["C","EAP"],["D","OpenID"]],"correct":"B"},{"num":31,"text":"A user, who is waiting for a flight at an airport, logs in to the airline website using the public Wi-Fi, ignores a\nsecurity warning and purchases an upgraded seat. When the flight lands, the user finds unauthorized credit\ncard charges. Which of the following attacks most likely occurred?","options":[["A","Replay attack"],["B","Memory leak"],["C","Buffer overflow attack"],["D","On-path attack"]],"correct":"D"},{"num":32,"text":"A network engineer deployed a redundant switch stack to increase system availability. However, the budget\ncan only cover the cost of one ISP connection. Which of the following best describes the potential risk\nfactor?","options":[["A","The equipment MTBF is unknown."],["B","The ISP has no SLA."],["C","An RPO has not been determined."],["D","There is a single point of failure."]],"correct":"D"},{"num":33,"text":"A network team segmented a critical, end-of-life server to a VLAN that can only be reached by specific\ndevices but cannot be reached by the perimeter network. Which of the following best describe the controls\nthe team implemented? (Choose two.)","options":[["A","Managerial"],["B","Physical"],["C","Corrective"],["D","Detective"],["E","Compensating"],["F","Technical"]],"correct":"EF"},{"num":34,"text":"A threat actor was able to use a username and password to log in to a stolen company mobile device.\nWhich of the following provides the best solution to increase mobile data security on all employees'\ncompany mobile devices?","options":[["A","Application management"],["B","Full disk encryption"],["C","Remote wipe"],["D","Containerization"]],"correct":"B"},{"num":35,"text":"Which of the following best describes the risk present after controls and mitigating factors have been\napplied?","options":[["A","Residual"],["B","Avoided"],["C","Inherent"],["D","Operational"]],"correct":"A"},{"num":36,"text":"A software development team asked a security administrator to recommend techniques that should be used\nto reduce the chances of the software being reverse engineered. Which of the following should the security\nadministrator recommend?","options":[["A","Digitally signing the software"],["B","Performing code obfuscation"],["C","Limiting the use of third-party libraries"],["D","Using compile flags"]],"correct":"B"},{"num":37,"text":"Which of the following is a possible factor for MFA?","options":[["A","Something you exhibit"],["B","Something you have"],["C","Somewhere you are"],["D","Someone you know"]],"correct":"B"},{"num":38,"text":"Easy-to-guess passwords led to an account compromise. The current password policy requires at least 12\nalphanumeric characters, one uppercase character, one lowercase character, a password history of two\npasswords, a minimum password age of one day, and a maximum password age of 90 days. Which of the\nfollowing would reduce the risk of this incident from happening again? (Choose two.)","options":[["A","Increasing the minimum password length to 14 characters."],["B","Upgrading the password hashing algorithm from MD5 to SHA-512."],["C","Increasing the maximum password age to 120 days."],["D","Reducing the minimum password length to ten characters."],["E","Reducing the minimum password age to zero days."],["F","Including a requirement for at least one special character."]],"correct":"AF"},{"num":39,"text":"A user downloaded software from an online forum. After the user installed the software, the security team\nobserved external network traffic connecting to the user's computer on an uncommon port. Which of the\nfollowing is the most likely explanation of this unauthorized connection?","options":[["A","The software had a hidden keylogger."],["B","The software was ransomware."],["C","The user's computer had a fileless virus."],["D","The software contained a backdoor."]],"correct":"D"},{"num":40,"text":"A utility company is designing a new platform that will host all the virtual machines used by business\napplications. The requirements include:\nA starting baseline of 50% memory utilization\nStorage scalability\nSingle circuit failure resilience\nWhich of the following best meets all of these requirements?","options":[["A","Connecting dual PDUs to redundant power supplies"],["B","Transitioning the platform to an IaaS provider"],["C","Configuring network load balancing for multiple paths"],["D","Deploying multiple large NAS devices for each host"]],"correct":"B"},{"num":41,"text":"Which of the following best describes a use case for a DNS sinkhole?","options":[["A","Attackers can see a DNS sinkhole as a highly valuable resource to identify a company's domain"],["B","A DNS sinkhole can be used to draw employees away from known-good websites to malicious ones"],["C","A DNS sinkhole can be used to capture traffic to known-malicious domains used by attackers."],["D","A DNS sinkhole can be set up to attract potential attackers away from a company's network resources."]],"correct":"C"},{"num":42,"text":"An incident analyst finds several image files on a hard disk. The image files may contain geolocation\ncoordinates. Which of the following best describes the type of information the analyst is trying to extract\nfrom the image files?","options":[["A","Log data"],["B","Metadata"],["C","Encrypted data"],["D","Sensitive data"]],"correct":"B"},{"num":43,"text":"Which of the following most likely describes why a security engineer would configure all outbound emails to\nuse S/MIME digital signatures?","options":[["A","To meet compliance standards"],["B","To increase delivery rates"],["C","To block phishing attacks"],["D","To ensure non-repudiation"]],"correct":"D"},{"num":44,"text":"During a recent company safety stand-down, the cyber-awareness team gave a presentation on the\nimportance of cyber hygiene. One topic the team covered was best practices for printing centers. Which of\nthe following describes an attack method that relates to printing centers?","options":[["A","Whaling"],["B","Credential harvesting"],["C","Prepending"],["D","Dumpster diving"]],"correct":"D"},{"num":45,"text":"Which of the following considerations is the most important regarding cryptography used in an IoT device?","options":[["A","Resource constraints"],["B","Available bandwidth"],["C","The use of block ciphers"],["D","The compatibility of the TLS version"]],"correct":"A"},{"num":46,"text":"A coffee shop owner wants to restrict internet access to only paying customers by prompting them for a\nreceipt number. Which of the following is the best method to use given this requirement?","options":[["A","WPA3"],["B","Captive portal"],["C","PSK"],["D","IEEE 802.1X"]],"correct":"B"},{"num":47,"text":"While performing digital forensics, which of the following is considered the most volatile and should have\nthe contents collected first?","options":[["A","Hard drive"],["B","RAM"],["C","SSD"],["D","Temporary files"]],"correct":"B"},{"num":48,"text":"A hosting provider needs to prove that its security controls have been in place over the last six months and\nhave sufficiently protected customer data. Which of the following would provide the best proof that the\nhosting provider has met the requirements?","options":[["A","NIST CSF"],["B","SOC 2 Type 2 report"],["C","CIS Top 20 compliance reports"],["D","Vulnerability report"]],"correct":"B"},{"num":49,"text":"A city municipality lost its primary data center when a tornado hit the facility. Which of the following should\nthe city staff use immediately after the disaster to handle essential public services?","options":[["A","BCP"],["B","Communication plan"],["C","DRP"],["D","IRP"]],"correct":"C"},{"num":50,"text":"Which of the following is considered a preventive control?","options":[["A","Configuration auditing"],["B","Log correlation"],["C","Incident alerts"],["D","Segregation of duties"]],"correct":"D"},{"num":51,"text":"A systems administrator notices that a testing system is down. While investigating, the systems\nadministrator finds that the servers are online and accessible from any device on the server network. The\nadministrator reviews the following information from the monitoring system:\n\nWhich of the following is the most likely cause of the outage?","options":[["A","Denial of service"],["B","ARP poisoning"],["C","Jamming"],["D","Kerberoasting"]],"correct":"A"},{"num":52,"text":"A security team has been alerted to a flood of incoming emails that have various subject lines and are\naddressed to multiple email inboxes. Each email contains a URL shortener link that is redirecting to a dead\ndomain. Which of the following is the best step for the security team to take?","options":[["A","Create a blocklist for all subject lines."],["B","Send the dead domain to a DNS sinkhole."],["C","Quarantine all emails received and notify all employees."],["D","Block the URL shortener domain in the web proxy."]],"correct":"D"},{"num":53,"text":"A security administrator is working to secure company data on corporate laptops in case the laptops are\nstolen. Which of the following solutions should the administrator consider?","options":[["A","Disk encryption"],["B","Data loss prevention"],["C","Operating system hardening"],["D","Boot security"]],"correct":"A"},{"num":54,"text":"A company needs to keep the fewest records possible, meet compliance needs, and ensure destruction of\nrecords that are no longer needed. Which of the following best describes the policy that meets these\nrequirements?","options":[["A","Security policy"],["B","Classification policy"],["C","Retention policy"],["D","Access control policy"]],"correct":"C"},{"num":55,"text":"Which of the following is a common source of unintentional corporate credential leakage in cloud\nenvironments?","options":[["A","Code repositories"],["B","Dark web"],["C","Threat feeds"],["D","State actors"],["E","Vulnerability databases"]],"correct":"A"},{"num":56,"text":"Which of the following is the best reason an organization should enforce a data classification policy to help\nprotect its most sensitive information?","options":[["A","End users will be required to consider the classification of data that can be used in documents."],["B","The policy will result in the creation of access levels for each level of classification."],["C","The organization will have the ability to create security requirements based on classification levels."],["D","Security analysts will be able to see the classification of data within a document before opening it."]],"correct":"C"},{"num":57,"text":"An analyst is performing a vulnerability scan against the web servers exposed to the internet without a\nsystem account. Which of the following is most likely being performed?","options":[["A","Non-credentialed scan"],["B","Packet capture"],["C","Privilege escalation"],["D","System enumeration"],["E","Passive scan"]],"correct":"A"},{"num":58,"text":"A security administrator is hardening corporate systems and applying appropriate mitigations by consulting\na real-world knowledge base for adversary behavior. Which of the following would be best for the\nadministrator to reference?","options":[["A","MITRE ATT&CK"],["B","CSIRT"],["C","CVSS"],["D","SOAR"]],"correct":"A"},{"num":59,"text":"An architect has a request to increase the speed of data transfer using JSON requests externally. Currently,\nthe organization uses SFTP to transfer data files. Which of the following will most likely meet the\nrequirements?","options":[["A","A website-hosted solution"],["B","Cloud shared storage"],["C","A secure email solution"],["D","Microservices using API"]],"correct":"D"},{"num":60,"text":"Which of the following addresses individual rights such as the right to be informed, the right of access, and\nthe right to be forgotten?","options":[["A","GDPR"],["B","PCI DSS"],["C","NIST"],["D","ISO"]],"correct":"A"},{"num":61,"text":"An administrator is installing an LDAP browser tool in order to view objects in the corporate LDAP directory.\nSecure connections to the LDAP server are required. When the browser connects to the server, certificate\nerrors are being displayed, and then the connection is terminated. Which of the following is the most likely\nsolution?","options":[["A","The administrator should allow SAN certificates in the browser configuration."],["B","The administrator needs to install the server certificate into the local truststore."],["C","The administrator should request that the secure LDAP port be opened to the server."],["D","The administrator needs to increase the TLS version on the organization's RA."]],"correct":"B"},{"num":62,"text":"Which of the following is the most important security concern when using legacy systems to provide\nproduction service?","options":[["A","Instability"],["B","Lack of vendor support"],["C","Loss of availability"],["D","Use of insecure protocols"]],"correct":"B"},{"num":63,"text":"A security investigation revealed that malicious software was installed on a server using a server\nadministrator's credentials. During the investigation, the server administrator explained that Telnet was\nregularly used to log in. Which of the following most likely occurred?","options":[["A","A spraying attack was used to determine which credentials to use."],["B","A packet capture tool was used to steal the password."],["C","A remote-access Trojan was used to install the malware."],["D","A dictionary attack was used to log in as the server administrator."]],"correct":"B"},{"num":64,"text":"A user is requesting Telnet access to manage a remote development web server. Insecure protocols are\nnot allowed for use within any environment. Which of the following should be configured to allow remote\naccess to this server?","options":[["A","HTTPS"],["B","SNMPv3"],["C","SSH"],["D","RDP"],["E","SMTP"]],"correct":"C"},{"num":65,"text":"A security administrator is working to find a cost-effective solution to implement certificates for a large\nnumber of domains and subdomains owned by the company. Which of the following types of certificates\nshould the administrator implement?","options":[["A","Wildcard"],["B","Client certificate"],["C","Self-signed"],["D","Code signing"]],"correct":"A"},{"num":66,"text":"An auditor discovered multiple insecure ports on some servers. Other servers were found to have legacy\nprotocols enabled. Which of the following tools did the auditor use to discover these issues?","options":[["A","Nessus"],["B","curl"],["C","Wireshark"],["D","netcat"]],"correct":"A"},{"num":67,"text":"A security analyst received a tip that sensitive proprietary information was leaked to the public. The analyst\nis reviewing the PCAP and notices traffic between an internal server and an external host that includes the\nfollowing:\n...\n12:47:22.327233 PPPoE [ses 0x8122] IP (tos 0x0, ttl 64, id 0, offset 0, flags\n[DF], proto IPv6 (41), length 331) 10.5.1.1 > 52.165.16.154: IP6 (hlim E3,\nnext-header TCP (6) paylcad length: 271) 2001:67c:2158:a019::ace.53104 >\n2001:0:5ef5:79fd:380c:dddd:a601:24fa.13788: Flags [P.], cksum 0xd7ee (correct),\nseq 97:348, ack 102, win 16444, length 251\n...\nWhich of the following was most likely used to exfiltrate the data?","options":[["A","Encapsulation"],["B","MAC address spoofing"],["C","Steganography"],["D","Broken encryption"],["E","Sniffing via on-path position"]],"correct":"A"},{"num":68,"text":"A company wants to reduce the time and expense associated with code deployment. Which of the following\ntechnologies should the company utilize?","options":[["A","Serverless architecture"],["B","Thin clients"],["C","Private cloud"],["D","Virtual machines"]],"correct":"A"},{"num":69,"text":"A security administrator is performing an audit on a stand-alone UNIX server, and the following message is\nimmediately displayed:\n(Error 13): /etc/shadow: Permission denied.\nWhich of the following best describes the type of tool that is being used?","options":[["A","Pass-the-hash monitor"],["B","File integrity monitor"],["C","Forensic analysis"],["D","Password cracker"]],"correct":"D"},{"num":70,"text":"A security administrator needs to create firewall rules for the following protocols: RTP, SIP, H.323. and\nSRTP. Which of the following does this rule set support?","options":[["A","RTOS"],["B","VoIP"],["C","SoC"],["D","HVAC"]],"correct":"B"},{"num":71,"text":"Which of the following best describes a social engineering attack that uses a targeted electronic messaging\ncampaign aimed at a Chief Executive Officer?","options":[["A","Whaling"],["B","Spear phishing"],["C","Impersonation"],["D","Identity fraud"]],"correct":"A"},{"num":72,"text":"During a penetration test, a flaw in the internal PKI was exploited to gain domain administrator rights using\nspecially crafted certificates. Which of the following remediation tasks should be completed as part of the\ncleanup phase?","options":[["A","Updating the CRL"],["B","Patching the CA"],["C","Changing passwords"],["D","Implementing SOAR"]],"correct":"B"},{"num":73,"text":"A company wants to implement MFA. Which of the following enables the additional factor while using a\nsmart card?","options":[["A","PIN"],["B","Hardware token"],["C","User ID"],["D","SMS"]],"correct":"A"},{"num":74,"text":"A company hired an external consultant to assist with required system upgrades to a critical business\napplication. A systems administrator needs to secure the consultant's access without sharing passwords to\ncritical systems. Which of the following solutions should most likely be utilized?","options":[["A","TACACS+"],["B","SAML"],["C","An SSO platform"],["D","Role-based access control"],["E","PAM software"]],"correct":"E"},{"num":75,"text":"A newly implemented wireless network is designed so that visitors can connect to the wireless network for\nbusiness activities. The legal department is concerned that visitors might connect to the network and\nperform illicit activities. Which of me following should the security team implement to address this concern?","options":[["A","Configure a RADIUS server to manage device authentication."],["B","Use 802.1X on all devices connecting to wireless."],["C","Add a guest captive portal requiring visitors to accept terms and conditions."],["D","Allow for new devices to be connected via WPS."]],"correct":"C"},{"num":76,"text":"Which of the following data roles is responsible for identifying risks and appropriate access to data?","options":[["A","Owner"],["B","Custodian"],["C","Steward"],["D","Controller"]],"correct":"A"},{"num":77,"text":"Which of the following physical controls can be used to both detect and deter? (Choose two.)","options":[["A","Lighting"],["B","Fencing"],["C","Signage"],["D","Sensor"],["E","Bollard"],["F","Lock"]],"correct":"AD"},{"num":78,"text":"A multinational bank hosts several servers in its data center. These servers run a business-critical\napplication used by customers to access their account information. Which of the following should the bank\nuse to ensure accessibility during peak usage times?","options":[["A","Load balancer"],["B","Cloud backups"],["C","Geographic dispersal"],["D","Disk multipathing"]],"correct":"A"},{"num":79,"text":"The author of a software package is concerned about bad actors repackaging and inserting malware into\nthe software. The software download is hosted on a website, and the author exclusively controls the\nwebsite's contents. Which of the following techniques would best ensure the software's integrity?","options":[["A","Input validation"],["B","Code signing"],["C","Secure cookies"],["D","Fuzzing"]],"correct":"B"},{"num":80,"text":"A third-party vendor is moving a particular application to the end-of-life stage at the end of the current year.\nWhich of the following is the most critical risk if the company chooses to continue running the application?","options":[["A","Lack of security updates"],["B","Lack of new features"],["C","Lack of support"],["D","Lack of source code access"]],"correct":"A"},{"num":81,"text":"A security analyst recently read a report about a flaw in several of the organization's printer models that\ncauses credentials to be sent over the network in cleartext, regardless of the encryption settings. Which of\nthe following would be best to use to validate this finding?","options":[["A","Wireshark"],["B","netcat"],["C","Nessus"],["D","Nmap"]],"correct":"A"},{"num":82,"text":"A development team is launching a new public-facing web product. The Chief Information Security Officer\nhas asked that the product be protected from attackers who use malformed or invalid inputs to destabilize\nthe system. Which of the following practices should the development team implement?","options":[["A","Fuzzing"],["B","Continuous deployment"],["C","Static code analysis"],["D","Manual peer review"]],"correct":"A"},{"num":83,"text":"During an annual review of the system design, an engineer identified a few issues with the currently\nreleased design. Which of the following should be performed next according to best practices?","options":[["A","Risk management process"],["B","Product design process"],["C","Design review process"],["D","Change control process"]],"correct":"D"},{"num":84,"text":"Which of the following is best to use when determining the severity of a vulnerability?","options":[["A","CVE"],["B","OSINT"],["C","SOAR"],["D","CVSS"]],"correct":"D"},{"num":85,"text":"An organization experienced a security breach that allowed an attacker to send fraudulent wire transfers\nfrom a hardened PC exclusively to the attacker's bank through remote connections. A security analyst is\ncreating a timeline of events and has found a different PC on the network containing malware. Upon\nreviewing the command history, the analyst finds the following:\nPS>.\\mimikatz.exe \"sekurlsa::pth /user:localadmin /domain:corp-domain.com /\nntlm:B4B9B02E1F29A3CF193EAB28C8D617D3F327\nWhich of the following best describes how the attacker gained access to the hardened PC?","options":[["A","The attacker created fileless malware that was hosted by the banking platform."],["B","The attacker performed a pass-the-hash attack using a shared support account."],["C","The attacker utilized living-off-the-land binaries to evade endpoint detection and response software."],["D","The attacker socially engineered the accountant into performing bad transfers."]],"correct":"B"},{"num":86,"text":"Which of the following is the best resource to consult for information on the most common application\nexploitation methods?","options":[["A","OWASP"],["B","STIX"],["C","OVAL"],["D","Threat intelligence feed"],["E","Common Vulnerabilities and Exposures"]],"correct":"A"},{"num":87,"text":"A security analyst is reviewing the logs on an organization's DNS server and notices the following unusual\nsnippet:\n\nWhich of the following attack techniques was most likely used?","options":[["A","Determining the organization's ISP-assigned address space"],["B","Bypassing the organization's DNS sinkholing"],["C","Footprinting the internal network"],["D","Attempting to achieve initial access to the DNS server"],["E","Exfiltrating data from fshare.int.complia.org"]],"correct":"C"},{"num":88,"text":"A security analyst at an organization observed several user logins from outside the organization's network.\nThe analyst determined that these logins were not performed by individuals within the organization. Which\nof the following recommendations would reduce the likelihood of future attacks? (Choose two.)","options":[["A","Disciplinary actions for users"],["B","Conditional access policies"],["C","More regular account audits"],["D","Implementation of additional authentication factors"],["E","Enforcement of content filtering policies"],["F","A review of user account permissions"]],"correct":"BD"},{"num":89,"text":"A security team is addressing a risk associated with the attack surface of the organization's web application\nover port 443. Currently, no advanced network security capabilities are in place. Which of the following\nwould be best to set up? (Choose two.)","options":[["A","NIDS"],["B","Honeypot"],["C","Certificate revocation list"],["D","HIPS"],["E","WAF"],["F","SIEM"]],"correct":"AE"},{"num":90,"text":"A systems administrator would like to create a point-in-time backup of a virtual machine. Which of the\nfollowing should the administrator use?","options":[["A","Replication"],["B","Simulation"],["C","Snapshot"],["D","Containerization"]],"correct":"C"},{"num":91,"text":"A security administrator notices numerous unused, non-compliant desktops are connected to the network.\nWhich of the following actions would the administrator most likely recommend to the management team?","options":[["A","Monitoring"],["B","Decommissioning"],["C","Patching"],["D","Isolating"]],"correct":"B"},{"num":92,"text":"Which of the following is a common data removal option for companies that want to wipe sensitive data\nfrom hard drives in a repeatable manner but allow the hard drives to be reused?","options":[["A","Sanitization"],["B","Formatting"],["C","Degaussing"],["D","Defragmentation"]],"correct":"A"},{"num":93,"text":"An organization wants to improve the company's security authentication method for remote employees.\nGiven the following requirements:\nMust work across SaaS and internal network applications\nMust be device manufacturer agnostic\nMust have offline capabilities\nWhich of the following would be the most appropriate authentication method?","options":[["A","Username and password"],["B","Biometrics"],["C","SMS verification"],["D","Time-based tokens"]],"correct":"D"},{"num":94,"text":"A security officer is implementing a security awareness program and has placed security-themed posters\naround the building and assigned online user training. Which of the following will the security officer most\nlikely implement?","options":[["A","Password policy"],["B","Access badges"],["C","Phishing campaign"],["D","Risk assessment"]],"correct":"C"},{"num":95,"text":"A malicious update was distributed to a common software platform and disabled services at many\norganizations. Which of the following best describes this type of vulnerability?","options":[["A","DDoS attack"],["B","Rogue employee"],["C","Insider threat"],["D","Supply chain"]],"correct":"D"},{"num":96,"text":"A company web server is initiating outbound traffic to a low-reputation, public IP on non-standard pat. The\nweb server is used to present an unauthenticated page to clients who upload images the company. An\nanalyst notices a suspicious process running on the server hat was not created by the company\ndevelopment team. Which of the following is the most likely explanation for his security incident?","options":[["A","A web shell has been deployed to the server through the page."],["B","A vulnerability has been exploited to deploy a worm to the server."],["C","Malicious insiders are using the server to mine cryptocurrency."],["D","Attackers have deployed a rootkit Trojan to the server over an exposed RDP port."]],"correct":"A"},{"num":97,"text":"An organization requests a third-party full-spectrum analysis of its supply chain. Which of the following\nwould the analysis team use to meet this requirement?","options":[["A","Vulnerability scanner"],["B","Penetration test"],["C","SCAP"],["D","Illumination tool"]],"correct":"D"},{"num":98,"text":"A systems administrator deployed a monitoring solution that does not require installation on the endpoints\nthat the solution is monitoring. Which of the following is described in this scenario?","options":[["A","Agentless solution"],["B","Client-based soon"],["C","Open port"],["D","File-based solution"]],"correct":"A"},{"num":99,"text":"A security analyst is reviewing the source code of an application in order to identify misconfigurations and\nvulnerabilities. Which of the following kinds of analysis best describes this review?","options":[["A","Dynamic"],["B","Static"],["C","Gap"],["D","Impact"]],"correct":"B"},{"num":100,"text":"Which of the following agreement types is used to limit external discussions?","options":[["A","BPA"],["B","NDA"],["C","SLA"],["D","MSA"]],"correct":"B"},{"num":101,"text":"A security analyst is evaluating a SaaS application that the human resources department would like to\nimplement. The analyst requests a SOC 2 report from the SaaS vendor. Which of the following processes is\nthe analyst most likely conducting?","options":[["A","Internal audit"],["B","Penetration testing"],["C","Attestation"],["D","Due diligence"]],"correct":"D"},{"num":102,"text":"Which of the following is used to conceal credit card information in a database log file?","options":[["A","Tokenization"],["B","Masking"],["C","Hashing"],["D","Obfuscation"]],"correct":"B"},{"num":104,"text":"An organization recently started hosting a new service that customers access through a web portal. A\nsecurity engineer needs to add to the existing security devices a new solution to protect this new service.\nWhich of the following is the engineer most likely to deploy?","options":[["A","Layer 4 firewall"],["B","NGFW"],["C","WAF"],["D","UTM"]],"correct":"C"},{"num":105,"text":"Which of the following topics would most likely be included within an organization's SDLC?","options":[["A","Service-level agreements"],["B","Information security policy"],["C","Penetration testing methodology"],["D","Branch protection requirements"]],"correct":"D"},{"num":106,"text":"Which of the following control types is AUP an example of?","options":[["A","Physical"],["B","Managerial"],["C","Technical"],["D","Operational"]],"correct":"D"},{"num":107,"text":"An organization is adopting cloud services at a rapid pace and now has multiple SaaS applications in use.\nEach application has a separate log-in, so the security team wants to reduce the number of credentials\neach employee must maintain. Which of the following is the first step the security team should take?","options":[["A","Enable SAML."],["B","Create OAuth tokens."],["C","Use password vaulting."],["D","Select an IdP."]],"correct":"D"},{"num":108,"text":"A company's online shopping website became unusable shortly after midnight on January 30, 2023. When\na security analyst reviewed the database server, the analyst noticed the following code used for backing up\ndata:\n\nWhich of the following should the analyst do next?","options":[["A","Check for recently terminated DBAs."],["B","Review WAF logs for evidence of command injection."],["C","Scan the database server for malware."],["D","Search the web server for ransomware notes."]],"correct":"B"},{"num":109,"text":"Which of the following would be the best way to test resiliency in the event of a primary power failure?","options":[["A","Parallel processing"],["B","Tabletop exercise"],["C","Simulation testing"],["D","Production failover"]],"correct":"D"},{"num":110,"text":"Which of the following would be the most appropriate way to protect data in transit?","options":[["A","SHA-256"],["B","SSL3.0"],["C","TLS 1.3"],["D","AES-256"]],"correct":"C"},{"num":111,"text":"Which of the following is a common, passive reconnaissance technique employed by penetration testers in\nthe early phases of an engagement?","options":[["A","Open-source intelligence"],["B","Port scanning"],["C","Pivoting"],["D","Exploit validation"]],"correct":"A"},{"num":112,"text":"Which of the following threat actors is the most likely to seek financial gain through the use of ransomware\nattacks?","options":[["A","Organized crime"],["B","Insider threat"],["C","Nation-state"],["D","Hacktivists"]],"correct":"A"},{"num":113,"text":"Which of the following would a systems administrator follow when upgrading the firmware of an\norganization\u2019s router?","options":[["A","Software development life cycle"],["B","Risk tolerance"],["C","Certificate signing request"],["D","Maintenance window"]],"correct":"D"},{"num":114,"text":"The security team has been asked to only enable host A (10.2.2.7) and host B (10.3.9.9) to the new isolated\nnetwork segment (10.9.8.14) that provides access to legacy devices.\nAccess from all other hosts should be blocked. Which of the following entries would need to be added on\nthe firewall?","options":[["A","B."],["C","D."]],"correct":"C"},{"num":116,"text":"A systems administrator needs to ensure the secure communication of sensitive data within the\norganization\u2019s private cloud. Which of the following is the best choice for the administrator to implement?","options":[["A","IPSec"],["B","SHA-1"],["C","RSA"],["D","TGT"]],"correct":"A"},{"num":117,"text":"Which of the following should an internal auditor check for first when conducting an audit of the\norganization\u2019s risk management program?","options":[["A","Policies and procedures"],["B","Asset management"],["C","Vulnerability assessment"],["D","Business impact analysis"]],"correct":"A"},{"num":118,"text":"Which of the following activities are associated with vulnerability management? (Choose two.)","options":[["A","Reporting"],["B","Prioritization"],["C","Exploiting"],["D","Correlation"],["E","Containment"],["F","Tabletop exercise"]],"correct":"AB"},{"num":119,"text":"An administrator wants to perform a risk assessment without using proprietary company information. Which\nof the following methods should the administrator use to gather information?","options":[["A","Network scanning"],["B","Penetration testing"],["C","Open-source intelligence"],["D","Configuration auditing"]],"correct":"C"},{"num":120,"text":"A systems administrator is concerned about vulnerabilities within cloud computing instances. Which of the\nfollowing is most important for the administrator to consider when architecting a cloud computing\nenvironment?","options":[["A","SQL injection"],["B","TOC/TOU"],["C","VM escape"],["D","Tokenization"],["E","Password spraying"]],"correct":"C"},{"num":121,"text":"A database administrator is updating the company\u2019s SQL database, which stores credit card information for\npending purchases. Which of the following is the best method to secure the data against a potential\nbreach?","options":[["A","Hashing"],["B","Obfuscation"],["C","Tokenization"],["D","Masking"]],"correct":"C"},{"num":122,"text":"Which of the following is a benefit of vendor diversity?","options":[["A","Patch availability"],["B","Zero-day resiliency"],["C","Secure configuration guide applicability"],["D","Load balancing"]],"correct":"B"},{"num":123,"text":"An employee used a company\u2019s billing system to issue fraudulent checks. The administrator is looking for\nevidence of other occurrences of this activity. Which of the following should the administrator examine?","options":[["A","Application logs"],["B","Vulnerability scanner logs"],["C","IDS/IPS logs"],["D","Firewall logs"]],"correct":"A"},{"num":124,"text":"An organization is looking to optimize its environment and reduce the number of patches necessary for\noperating systems. Which of the following will best help to achieve this objective?","options":[["A","Microservices"],["B","Virtualization"],["C","Real-time operating system"],["D","Containers"]],"correct":"D"},{"num":125,"text":"Which of the following tasks is typically included in the BIA process?","options":[["A","Estimating the recovery time of systems"],["B","Identifying the communication strategy"],["C","Evaluating the risk management plan"],["D","Establishing the backup and recovery procedures"],["E","Developing the incident response plan"]],"correct":"A"},{"num":126,"text":"Which of the following is a risk of conducting a vulnerability assessment?","options":[["A","A disruption of business operations"],["B","Unauthorized access to the system"],["C","Reports of false positives"],["D","Finding security gaps in the system"]],"correct":"A"},{"num":127,"text":"Which of the following techniques would attract the attention of a malicious attacker in an insider threat\nscenario?","options":[["A","Creating a false text file in /docs/salaries"],["B","Setting weak passwords in /etc/shadow"],["C","Scheduling vulnerable jobs in /etc/crontab"],["D","Adding a fake account to /etc/passwd"]],"correct":"A"},{"num":128,"text":"An organization maintains intellectual property that it wants to protect. Which of the following concepts\nwould be most beneficial to add to the company\u2019s security awareness training program?","options":[["A","Insider threat detection"],["B","Simulated threats"],["C","Phishing awareness"],["D","Business continuity planning"]],"correct":"A"},{"num":129,"text":"An organization plans to expand its operations internationally and needs to keep data at the new location\nsecure. The organization wants to use the most secure architecture model possible. Which of the following\nmodels offers the highest level of security?","options":[["A","Cloud-based"],["B","Peer-to-peer"],["C","On-premises"],["D","Hybrid"]],"correct":"C"},{"num":130,"text":"Which of the following is the most relevant reason a DPO would develop a data inventory?","options":[["A","To manage data storage requirements better"],["B","To determine the impact in the event of a breach"],["C","To extend the length of time data can be retained"],["D","To automate the reduction of duplicated data"]],"correct":"B"},{"num":131,"text":"Which of the following cryptographic solutions protects data at rest?","options":[["A","Digital signatures"],["B","Full disk encryption"],["C","Private key"],["D","Steganography"]],"correct":"B"},{"num":132,"text":"Which of the following should an organization use to protect its environment from external attacks\nconducted by an unauthorized hacker?","options":[["A","ACL"],["B","IDS"],["C","HIDS"],["D","NIPS"]],"correct":"D"},{"num":133,"text":"Which of the following would enable a data center to remain operational through a multiday power outage?","options":[["A","Generator"],["B","Uninterruptible power supply"],["C","Replication"],["D","Parallel processing"]],"correct":"A"},{"num":134,"text":"A company installed cameras and added signs to alert visitors that they are being recorded. Which of the\nfollowing controls did the company implement? (Choose two.)","options":[["A","Directive"],["B","Deterrent"],["C","Preventive"],["D","Detective"],["E","Corrective"],["F","Technical"]],"correct":"BD"},{"num":135,"text":"Which of the following is the best way to securely store an encryption key for a data set in a manner that\nallows multiple entities to access the key when needed?","options":[["A","Public key infrastructure"],["B","Open public ledger"],["C","Public key encryption"],["D","Key escrow"]],"correct":"D"},{"num":136,"text":"For which of the following reasons would a systems administrator leverage a 3DES hash from an installer\nfile that is posted on a vendor\u2019s website?","options":[["A","To test the integrity of the file"],["B","To validate the authenticity of the file"],["C","To activate the license for the file"],["D","To calculate the checksum of the file"]],"correct":"A"},{"num":137,"text":"A company is redesigning its infrastructure and wants to reduce the number of physical servers in use.\nWhich of the following architectures is best suited for this goal?","options":[["A","Isolation"],["B","Segmentation"],["C","Virtualization"],["D","Redundancy"]],"correct":"C"},{"num":138,"text":"Which of the following security concepts is being followed when implementing a product that offers\nprotection against DDoS attacks?","options":[["A","Availability"],["B","Non-repudiation"],["C","Integrity"],["D","Confidentiality"]],"correct":"A"},{"num":139,"text":"A security manager created new documentation to use in response to various types of security incidents.\nWhich of the following is the next step the manager should take?","options":[["A","Set the maximum data retention policy."],["B","Securely store the documents on an air-gapped network."],["C","Review the documents\u2019 data classification policy."],["D","Conduct a tabletop exercise with the team."]],"correct":"D"},{"num":140,"text":"After failing an audit twice, an organization has been ordered by a government regulatory agency to pay\nfines. Which of the following causes this action?","options":[["A","Non-compliance"],["B","Contract violations"],["C","Government sanctions"],["D","Rules of engagement"]],"correct":"A"},{"num":141,"text":"A company is developing a critical system for the government and storing project information on a fileshare.\nWhich of the following describes how this data will most likely be classified? (Choose two.)","options":[["A","Private"],["B","Confidential"],["C","Public"],["D","Operational"],["E","Urgent"],["F","Restricted"]],"correct":"BF"},{"num":142,"text":"Which of the following activities is included in the post-incident review phase?","options":[["A","Determining the root cause of the incident"],["B","Developing steps to mitigate the risks of the incident"],["C","Validating the accuracy of the evidence collected during the investigation"],["D","Reestablishing the compromised system\u2019s configuration and settings"]],"correct":"A"},{"num":143,"text":"Which of the following attacks exploits a potential vulnerability as a result of using weak cryptographic\nalgorithms?","options":[["A","Password cracking"],["B","On-path"],["C","Digital signing"],["D","Side-channel"]],"correct":"A"},{"num":144,"text":"Which of the following is a preventive physical security control?","options":[["A","Video surveillance system"],["B","Bollards"],["C","Alarm system"],["D","Motion sensors"]],"correct":"B"},{"num":145,"text":"Which of the following is most likely to be used as a just-in-time reference document within a security\noperations center?","options":[["A","Change management policy"],["B","Risk profile"],["C","Playbook"],["D","SIEM profile"]],"correct":"C"},{"num":146,"text":"A security engineer configured a remote access VPN. The remote access VPN allows end users to connect\nto the network by using an agent that is installed on the endpoint, which establishes an encrypted tunnel.\nWhich of the following protocols did the engineer most likely implement?","options":[["A","GRE"],["B","IPSec"],["C","SD-WAN"],["D","EAP"]],"correct":"B"},{"num":147,"text":"Executives at a company are concerned about employees accessing systems and information about\nsensitive company projects unrelated to the employees\u2019 normal job duties. Which of the following enterprise\nsecurity capabilities will the security team most likely deploy to detect that activity?","options":[["A","UBA"],["B","EDR"],["C","NAC"],["D","DLP"]],"correct":"A"},{"num":148,"text":"Several customers want an organization to verify its security controls are operating effectively and have\nrequested an independent opinion. Which of the following is the most efficient way to address these\nrequests?","options":[["A","Hire a vendor to perform a penetration test"],["B","Perform an annual self-assessment."],["C","Allow each client the right to audit"],["D","Provide a third-party attestation report"]],"correct":"D"},{"num":149,"text":"A university employee logged on to the academic server and attempted to guess the system administrators\u2019\nlog-in credentials. Which of the following security measures should the university have implemented to\ndetect the employee\u2019s attempts to gain access to the administrators\u2019 accounts?","options":[["A","Two-factor authentication"],["B","Firewall"],["C","Intrusion prevention system"],["D","User activity logs"]],"correct":"D"},{"num":150,"text":"Which of the following consequences would a retail chain most likely face from customers in the event the\nretailer is non-compliant with PCI DSS?","options":[["A","Contractual impacts"],["B","Sanctions"],["C","Fines"],["D","Reputational damage"]],"correct":"D"},{"num":151,"text":"A security analyst is reviewing logs and discovers the following:\n\nWhich of the following should be used to best mitigate this type of attack?","options":[["A","Input sanitization"],["B","Secure cookies"],["C","Static code analysis"],["D","Sandboxing"]],"correct":"A"},{"num":152,"text":"An administrator is installing an SSL certificate on a new system. During testing, errors indicate that the\ncertificate is not trusted. The administrator has verified with the issuing CA and has validated the private\nkey. Which of the following should the administrator check for next?","options":[["A","If the wildcard certificate is configured"],["B","If the certificate signing request is valid"],["C","If the root certificate is installed"],["D","If the public key is configured"]],"correct":"C"},{"num":153,"text":"An employee emailed a new systems administrator a malicious web link and convinced the administrator to\nchange the email server\u2019s password. The employee used this access to remove the mailboxes of key\npersonnel. Which of the following security awareness concepts would help prevent this threat in the future?","options":[["A","Recognizing phishing"],["B","Providing situational awareness training"],["C","Using password management"],["D","Reviewing email policies"]],"correct":"A"},{"num":154,"text":"Which of the following strategies should an organization use to efficiently manage and analyze multiple\ntypes of logs?","options":[["A","Deploy a SIEM solution"],["B","Create custom scripts to aggregate and analyze logs."],["C","Implement EDR technology."],["D","Install a unified threat management appliance."]],"correct":"A"},{"num":155,"text":"A new security regulation was announced that will take effect in the coming year. A company must comply\nwith it to remain in business. Which of the following activities should the company perform next?","options":[["A","Gap analysis"],["B","Policy review"],["C","Security procedure evaluation"],["D","Threat scope reduction"]],"correct":"A"},{"num":156,"text":"An accountant is transferring information to a bank over FTP. Which of the following mitigations should the\naccountant use to protect the confidentiality of the data?","options":[["A","Tokenization"],["B","Data masking"],["C","Encryption"],["D","Obfuscation"]],"correct":"C"},{"num":157,"text":"An organization has recently decided to implement SSO. The requirements are to leverage access tokens\nand focus on application authorization rather than user authentication. Which of the following solutions\nwould the engineering team most likely configure?","options":[["A","LDAP"],["B","Federation"],["C","SAML"],["D","OAuth"]],"correct":"D"},{"num":158,"text":"Which of the following would most likely be used by attackers to perform credential harvesting?","options":[["A","Social engineering"],["B","Supply chain compromise"],["C","Third-party software"],["D","Rainbow table"]],"correct":"A"},{"num":159,"text":"A security engineer would like to enhance the use of automation and orchestration within the SIEM. Which\nof the following would be the primary benefit of this enhancement?","options":[["A","It increases complexity."],["B","It removes technical debt."],["C","It adds additional guard rails."],["D","It acts as a workforce multiplier."]],"correct":"D"},{"num":160,"text":"A systems administrator receives an alert that a company\u2019s internal file server is very slow and is only\nworking intermittently. The systems administrator reviews the server management software and finds the\nfollowing information about the server:\n\nWhich of the following indicators most likely triggered this alert?","options":[["A","Concurrent session usage"],["B","Network saturation"],["C","Account lockout"],["D","Resource consumption"]],"correct":"D"},{"num":161,"text":"Which of the following data states applies to data that is being actively processed by a database server?","options":[["A","In use"],["B","At rest"],["C","In transit"],["D","Being hashed"]],"correct":"A"},{"num":162,"text":"Which of the following architectures is most suitable to provide redundancy for critical business processes?","options":[["A","Network-enabled"],["B","Server-side"],["C","Cloud-native"],["D","Multitenant"]],"correct":"C"},{"num":163,"text":"After a security incident, a systems administrator asks the company to buy a NAC platform. Which of the\nfollowing attack surfaces is the systems administrator trying to protect?","options":[["A","Bluetooth"],["B","Wired"],["C","NFC"],["D","SCADA"]],"correct":"B"},{"num":164,"text":"While reviewing logs, a security administrator identifies the following code:\n<script>function (send_info)</script>\nWhich of the following best describes the vulnerability being exploited?","options":[["A","XSS"],["B","SQLi"],["C","DDoS"],["D","CSRF"]],"correct":"A"},{"num":165,"text":"An organization issued new laptops to all employees and wants to provide web filtering both in and out of\nthe office without configuring additional access to the network. Which of the following types of web filtering\nshould a systems administrator configure?","options":[["A","Agent-based"],["B","Centralized proxy"],["C","URL scanning"],["D","Content categorization"]],"correct":"A"},{"num":166,"text":"Which of the following should be used to aggregate log data in order to create alerts and detect anomalous\nactivity?","options":[["A","SIEM"],["B","WAF"],["C","Network taps"],["D","IDS"]],"correct":"A"},{"num":167,"text":"Which of the following provides the best protection against unwanted or insecure communications to and\nfrom a device?","options":[["A","System hardening"],["B","Host-based firewall"],["C","Intrusion detection system"],["D","Anti-malware software"]],"correct":"B"},{"num":168,"text":"Which of the following is the primary purpose of a service that tracks log-ins and time spent using the\nservice?","options":[["A","Availability"],["B","Accounting"],["C","Authentication"],["D","Authorization"]],"correct":"B"},{"num":169,"text":"An employee who was working remotely lost a mobile device containing company data. Which of the\nfollowing provides the best solution to prevent future data loss?","options":[["A","MDM"],["B","DLP"],["C","FDE"],["D","EDR"]],"correct":"A"},{"num":170,"text":"An IT administrator needs to ensure data retention standards are implemented on an enterprise application.\nWhich of the following describes the administrator\u2019s role?","options":[["A","Processor"],["B","Custodian"],["C","Privacy officer"],["D","Owner"]],"correct":"B"},{"num":171,"text":"A company plans to secure its systems by:\nPreventing users from sending sensitive data over corporate email\nRestricting access to potentially harmful websites\nWhich of the following features should the company set up? (Choose two.)","options":[["A","DLP software"],["B","DNS filtering"],["C","File integrity monitoring"],["D","Stateful firewall"],["E","Guardrails"],["F","Antivirus signatures"]],"correct":"AB"},{"num":172,"text":"A company processes and stores sensitive data on its own systems. Which of the following steps should\nthe company take first to ensure compliance with privacy regulations?","options":[["A","Implement access controls and encryption."],["B","Develop and provide training on data protection policies."],["C","Create incident response and disaster recovery plans."],["D","Purchase and install security software."]],"correct":"B"},{"num":173,"text":"Which of the following cryptographic methods is preferred for securing communications with limited\ncomputing resources?","options":[["A","Hashing algorithm"],["B","Public key infrastructure"],["C","Symmetric encryption"],["D","Elliptic curve cryptography"]],"correct":"C"},{"num":174,"text":"A network administrator wants to ensure that network traffic is highly secure while in transit.\nWhich of the following actions best describes the actions the network administrator should take?","options":[["A","Ensure that NAC is enforced on all network segments, and confirm that firewalls have updated policies"],["B","Ensure only TLS and other encrypted protocols are selected for use on the network, and only permit"],["C","Configure the perimeter IPS to block inbound HTTPS directory traversal traffic, and verify that"],["D","Ensure the EDR software monitors for unauthorized applications that could be used by threat actors,"]],"correct":"B"},{"num":175,"text":"Which of the following definitions best describes the concept of log correlation?","options":[["A","Combining relevant logs from multiple sources into one location"],["B","Searching and processing data to identify patterns of malicious activity"],["C","Making a record of the events that occur in the system"],["D","Analyzing the log files of the system components"]],"correct":"B"},{"num":176,"text":"An enterprise security team is researching a new security architecture to better protect the company\u2019s\nnetworks and applications against the latest cyberthreats. The company has a fully remote workforce. The\nsolution should be highly redundant and enable users to connect to a VPN with an integrated, softwarebased firewall. Which of the following solutions meets these requirements?","options":[["A","IPS"],["B","SIEM"],["C","SASE"],["D","CASB"]],"correct":"C"},{"num":177,"text":"Which of the following is the best way to validate the integrity and availability of a disaster recovery site?","options":[["A","Lead a simulated failover."],["B","Conduct a tabletop exercise."],["C","Periodically test the generators."],["D","Develop requirements for database encryption."]],"correct":"A"},{"num":178,"text":"Which of the following allows an exploit to go undetected by the operating system?","options":[["A","Firmware vulnerabilities"],["B","Side loading"],["C","Memory injection"],["D","Encrypted payloads"]],"correct":"C"},{"num":179,"text":"A malicious insider from the marketing team alters records and transfers company funds to a personal\naccount. Which of the following methods would be the best way to secure company records in the future?","options":[["A","Permission restrictions"],["B","Hashing"],["C","Input validation"],["D","Access control list"]],"correct":"A"},{"num":180,"text":"An organization is required to provide assurance that its controls are properly designed and operating\neffectively. Which of the following reports will best achieve the objective?","options":[["A","Red teaming"],["B","Penetration testing"],["C","Independent audit"],["D","Vulnerability assessment"]],"correct":"C"},{"num":181,"text":"A systems administrator successfully configures VPN access to a cloud environment. Which of the\nfollowing capabilities should the administrator use to best facilitate remote administration?","options":[["A","A jump host in the shared services security zone"],["B","An SSH server within the corporate LAN"],["C","A reverse proxy on the firewall"],["D","An MDM solution with conditional access"]],"correct":"A"},{"num":182,"text":"Which of the following best describes the concept of information being stored outside of its country of origin\nwhile still being subject to the laws and requirements of the country of origin?","options":[["A","Data sovereignty"],["B","Geolocation"],["C","Intellectual property"],["D","Geographic restrictions"]],"correct":"A"},{"num":183,"text":"An audit reveals that cardholder database logs are exposing account numbers inappropriately. Which of the\nfollowing mechanisms would help limit the impact of this error?","options":[["A","Segmentation"],["B","Hashing"],["C","Journaling"],["D","Masking"]],"correct":"D"},{"num":184,"text":"A security analyst attempts to start a company's database server. When the server starts, the analyst\nreceives an error message indicating the database server did not pass authentication. After reviewing and\ntesting the system, the analyst receives confirmation that the server has been compromised and that\nattackers have redirected all outgoing database traffic to a server under their control. Which of the following\nMITRE ATT&CK techniques did the attacker most likely use to redirect database traffic?","options":[["A","Browser extension"],["B","Process injection"],["C","Valid accounts"],["D","Escape to host"]],"correct":"D"},{"num":185,"text":"A penetration tester enters an office building at the same time as a group of employees despite not having\nan access badge. Which of the following attack types is the penetration tester performing?","options":[["A","Tailgating"],["B","Shoulder surfing"],["C","RFID cloning"],["D","Forgery"]],"correct":"A"},{"num":186,"text":"Which of the following enables the ability to receive a consolidated report from different devices on the\nnetwork?","options":[["A","IPS"],["B","DLP"],["C","SIEM"],["D","Firewall"]],"correct":"C"},{"num":187,"text":"Which of the following should an organization focus on the most when making decisions about vulnerability\nprioritization?","options":[["A","Exposure factor"],["B","CVSS"],["C","CVE"],["D","Industry impact"]],"correct":"B"},{"num":188,"text":"An organization needs to monitor its users\u2019 activities in order to prevent insider threats. Which of the\nfollowing solutions would help the organization achieve this goal?","options":[["A","Behavioral analytics"],["B","Access control lists"],["C","Identity and access management"],["D","Network intrusion detection system"]],"correct":"A"},{"num":189,"text":"A customer of a large company receives a phone call from someone claiming to work for the company and\nasking for the customer\u2019s credit card information. The customer sees the caller ID is the same as the\ncompany's main phone number. Which of the following attacks is the customer most likely a target of?","options":[["A","Phishing"],["B","Whaling"],["C","Smishing"],["D","Vishing"]],"correct":"D"},{"num":190,"text":"A security analyst is reviewing logs to identify the destination of command-and-control traffic originating\nfrom a compromised device within the on-premises network. Which of the following is the best log to\nreview?","options":[["A","IDS"],["B","Antivirus"],["C","Firewall"],["D","Application"]],"correct":"C"},{"num":191,"text":"When trying to access an internal website, an employee reports that a prompt displays, stating that the site\nis insecure. Which of the following certificate types is the site most likely using?","options":[["A","Wildcard"],["B","Root of trust"],["C","Third-party"],["D","Self-signed"]],"correct":"D"},{"num":192,"text":"Which of the following would most likely be deployed to obtain and analyze attacker activity and\ntechniques?","options":[["A","Firewall"],["B","IDS"],["C","Honeypot"],["D","Layer 3 switch"]],"correct":"C"},{"num":193,"text":"Which of the following objectives is best achieved by a tabletop exercise?","options":[["A","Familiarizing participants with the incident response process"],["B","Deciding red and blue team rules of engagement"],["C","Quickly determining the impact of an actual security breach"],["D","Conducting multiple security investigations in parallel"]],"correct":"A"},{"num":194,"text":"The private key for a website was stolen, and a new certificate has been issued. Which of the following\nneeds to be updated next?","options":[["A","SCEP"],["B","CRL"],["C","OCSP"],["D","CSR"]],"correct":"B"},{"num":195,"text":"Which of the following organizational documents is most often used to establish and communicate\nexpectations associated with integrity and ethical behavior within an organization?","options":[["A","AUP"],["B","SLA"],["C","EULA"],["D","MOA"]],"correct":"A"},{"num":196,"text":"Which of the following explains how to determine the global regulations that data is subject to regardless of\nthe country where the data is stored?","options":[["A","Geographic dispersion"],["B","Data sovereignty"],["C","Geographic restrictions"],["D","Data segmentation"]],"correct":"B"},{"num":197,"text":"An organization's web servers host an online ordering system. The organization discovers that the servers\nare vulnerable to a malicious JavaScript injection, which could allow attackers to access customer payment\ninformation. Which of the following mitigation strategies would be most effective for preventing an attack on\nthe organization's web servers? (Choose two.)","options":[["A","Regularly updating server software and patches"],["B","Implementing strong password policies"],["C","Encrypting sensitive data at rest and in transit"],["D","Utilizing a web-application firewall"],["E","Performing regular vulnerability scans"],["F","Removing payment information from the servers"]],"correct":"AD"},{"num":198,"text":"Which of the following tools is best for logging and monitoring in a cloud environment?","options":[["A","IPS"],["B","FIM"],["C","NAC"],["D","SIEM"]],"correct":"D"},{"num":199,"text":"During a SQL update of a database, a temporary field that was created was replaced by an attacker in\norder to allow access to the system. Which of the following best describes this type of vulnerability?","options":[["A","Race condition"],["B","Memory injection"],["C","Malicious update"],["D","Side loading"]],"correct":"C"},{"num":200,"text":"A group of developers has a shared backup account to access the source code repository. Which of the\nfollowing is best way to secure the backup account if there is an SSO failure?","options":[["A","RAS"],["B","EAP"],["C","SAML"],["D","PAM"]],"correct":"D"},{"num":201,"text":"Which of the following elements of digital forensics should a company use if it needs to ensure the integrity\nof evidence?","options":[["A","Preservation"],["B","E-discovery"],["C","Acquisition"],["D","Containment"]],"correct":"A"},{"num":202,"text":"A company suffered a critical incident where 30GB of data was exfiltrated from the corporate network.\nWhich of the following actions is the most efficient way to identify where the system data was exfiltrated\nfrom and what location the attacker sent the data to?","options":[["A","Analyze firewall and network logs for large amounts of outbound traffic to external IP addresses or"],["B","Analyze IPS and IDS logs to find the IP addresses used by the attacker for reconnaissance scans."],["C","Analyze endpoint and application logs to see whether file-sharing programs were running on the"],["D","Analyze external vulnerability scans and automated reports to identify the systems the attacker could"]],"correct":"A"},{"num":203,"text":"Which of the following describes the procedures a penetration tester must follow while conducting a test?","options":[["A","Rules of engagement"],["B","Rules of acceptance"],["C","Rules of understanding"],["D","Rules of execution"]],"correct":"A"},{"num":204,"text":"A security analyst wants to better understand the behavior of users and devices in order to gain visibility into\npotential malicious activities. The analyst needs a control to detect when actions deviate from a common\nbaseline. Which of the following should the analyst use?","options":[["A","Intrusion prevention system"],["B","Sandbox"],["C","Endpoint detection and response"],["D","Antivirus"]],"correct":"C"},{"num":205,"text":"A legal department must maintain a backup from all devices that have been shredded and recycled by a\nthird party. Which of the following best describes this requirement?","options":[["A","Data retention"],["B","Certification"],["C","Sanitization"],["D","Destruction"]],"correct":"A"},{"num":206,"text":"Which of the following can be used to compromise a system that is running an RTOS?","options":[["A","Cross-site scripting"],["B","Memory injection"],["C","Replay attack"],["D","Ransomware"]],"correct":"B"},{"num":207,"text":"Which of the following threat actors would most likely deface the website of a high-profile music group?","options":[["A","Unskilled attacker"],["B","Organized crime"],["C","Nation-state"],["D","Insider threat"]],"correct":"A"},{"num":208,"text":"A security architect wants to prevent employees from receiving malicious attachments by email. Which of\nthe following functions should the chosen solution do?","options":[["A","Apply IP address reputation data."],["B","Tap and monitor the email feed."],["C","Scan email traffic inline."],["D","Check SPF records."]],"correct":"C"},{"num":209,"text":"Which of the following activities is the first stage in the incident response process?","options":[["A","Detection"],["B","Declaration"],["C","Containment"],["D","Verification"]],"correct":"A"},{"num":210,"text":"Which of the following is the main consideration when a legacy system that is a critical part of a company's\ninfrastructure cannot be replaced?","options":[["A","Resource provisioning"],["B","Cost"],["C","Single point of failure"],["D","Complexity"]],"correct":"C"},{"num":211,"text":"Which of the following is a compensating control for providing user access to a high-risk website?","options":[["A","Enabling threat prevention features on the firewall"],["B","Configuring a SIEM tool to capture all web traffic"],["C","Setting firewall rules to allow traffic from any port to that destination"],["D","Blocking that website on the endpoint protection software"]],"correct":"A"},{"num":212,"text":"An organization is implementing a COPE mobile device management policy. Which of the following should\nthe organization include in the COPE policy? (Choose two.)","options":[["A","Remote wiping of the device"],["B","Data encryption"],["C","Requiring passwords with eight characters"],["D","Data usage caps"],["E","Employee data ownership"],["F","Personal application store access"]],"correct":"AB"},{"num":213,"text":"A security administrator observed the following in a web server log while investigating an incident:\n\"GET\n\n../../../../etc/passwd\"\n\nWhich of the following attacks did the security administrator most likely see?","options":[["A","Privilege escalation"],["B","Credential replay"],["C","Brute force"],["D","Directory traversal"]],"correct":"D"},{"num":214,"text":"An organization wants a third-party vendor to do a penetration test that targets a specific device. The\norganization has provided basic information about the device. Which of the following best describes this\nkind of penetration test?","options":[["A","Partially known environment"],["B","Unknown environment"],["C","Integrated"],["D","Known environment"]],"correct":"A"},{"num":215,"text":"Which of the following should a security team do first before a new web server goes live?","options":[["A","Harden the virtual host."],["B","Create WAF rules."],["C","Enable network intrusion detection."],["D","Apply patch management."]],"correct":"A"},{"num":216,"text":"Which of the following techniques can be used to sanitize the data contained on a hard drive while allowing\nfor the hard drive to be repurposed?","options":[["A","Degaussing"],["B","Drive shredder"],["C","Retention platform"],["D","Wipe tool"]],"correct":"D"},{"num":217,"text":"An attacker submits a request containing unexpected characters in an attempt to gain unauthorized access\nto information within the underlying systems. Which of the following best describes this attack?","options":[["A","Side loading"],["B","Target of evaluation"],["C","Resource reuse"],["D","SQL injection"]],"correct":"D"},{"num":218,"text":"A security analyst has determined that a security breach would have a financial impact of $15,000 and is\nexpected to occur twice within a three-year period. Which of the following is the ALE for this risk?","options":[["A","$7,500"],["B","$10,000"],["C","$15,000"],["D","$30,000"]],"correct":"B"},{"num":219,"text":"A systems administrator discovers a system that is no longer receiving support from the vendor. However,\nthis system and its environment are critical to running the business, cannot be modified, and must stay\nonline. Which of the following risk treatments is the most appropriate in this situation?","options":[["A","Reject"],["B","Accept"],["C","Transfer"],["D","Avoid"]],"correct":"B"},{"num":220,"text":"A company discovered its data was advertised for sale on the dark web. During the initial investigation, the\ncompany determined the data was proprietary data. Which of the following is the next step the company\nshould take?","options":[["A","Identify the attacker\u2019s entry methods."],["B","Report the breach to the local authorities."],["C","Notify the applicable parties of the breach."],["D","Implement vulnerability scanning of the company's systems."]],"correct":"B"},{"num":221,"text":"Which of the following would be the best solution to deploy a low-cost standby site that includes hardware\nand internet access?","options":[["A","Recovery site"],["B","Cold site"],["C","Hot site"],["D","Warm site"]],"correct":"D"},{"num":222,"text":"An organization needs to determine how many employees are accessing the building each day in order to\nconfigure the proper access controls. Which of the following control types best meets this requirement?","options":[["A","Detective"],["B","Preventive"],["C","Corrective"],["D","Directive"]],"correct":"A"},{"num":223,"text":"An organization wants to implement a secure solution for remote users. The users handle sensitive PHI on\na regular basis and need to access an internally developed corporate application. Which of the following\nbest meet the organization's security requirements? (Choose two.)","options":[["A","Local administrative password"],["B","Perimeter network"],["C","Jump server"],["D","WAF"],["E","MFA"],["F","VPN"]],"correct":"EF"},{"num":224,"text":"A security officer is implementing a security awareness program and is placing security-themed posters\naround the building and is assigning online user training. Which of the following would the security officer\nmost likely implement?","options":[["A","Password policy"],["B","Access badges"],["C","Phishing campaign"],["D","Risk assessment"]],"correct":"C"},{"num":225,"text":"A security consultant is working with a client that wants to physically isolate its secure systems. Which of\nthe following best describes this architecture?","options":[["A","SDN"],["B","Air gapped"],["C","Containerized"],["D","Highly available"]],"correct":"B"},{"num":226,"text":"A company is in the process of migrating to cloud-based services. The company\u2019s IT department has\nlimited resources for migration and ongoing support. Which of the following best meets the company\u2019s\nneeds?","options":[["A","IPS"],["B","WAF"],["C","SASE"],["D","IAM"]],"correct":"C"},{"num":227,"text":"An employee clicks a malicious link in an email that appears to be from the company's Chief Executive\nOfficer. The employee's computer is infected with ransomware that encrypts the company's files. Which of\nthe following is the most effective way for the company to prevent similar incidents in the future?","options":[["A","Security awareness training"],["B","Database encryption"],["C","Segmentation"],["D","Reporting suspicious emails"]],"correct":"A"},{"num":228,"text":"Which of the following types of vulnerabilities is primarily caused by improper use and management of\ncryptographic certificates?","options":[["A","Misconfiguration"],["B","Resource reuse"],["C","Insecure key storage"],["D","Weak cipher suites"]],"correct":"C"},{"num":229,"text":"Which of the following best describe the benefits of a microservices architecture when compared to a\nmonolithic architecture? (Choose two.)","options":[["A","Easier debugging of the system"],["B","Reduced cost of ownership of the system"],["C","Improved scalability of the system"],["D","Increased compartmentalization of the system"],["E","Stronger authentication of the system"],["F","Reduced complexity of the system"]],"correct":"CD"},{"num":230,"text":"A user's workstation becomes unresponsive and displays a ransom note demanding payment to decrypt\nfiles. Before the attack, the user opened a resume they received in a message, browsed the company's\nwebsite, and installed OS updates. Which of the following is the most likely vector of this attack?","options":[["A","Spear-phishing attachment"],["B","Watering hole"],["C","Infected website"],["D","Typosquatting"]],"correct":"A"},{"num":231,"text":"A penetration tester finds an unused Ethernet port during an on-site penetration test. Upon plugging a\ndevice into the unused port, the penetration tester notices that the machine is assigned an IP address,\nallowing the tester to enumerate the local network. Which of the following should an administrator\nimplement in order to prevent this situation from happening in the future?","options":[["A","Port security"],["B","Transport Layer Security"],["C","Proxy server"],["D","Security zones"]],"correct":"A"},{"num":232,"text":"Which of the following should be used to ensure an attacker is unable to read the contents of a mobile\ndevice's drive if the device is lost?","options":[["A","TPM"],["B","ECC"],["C","FDE"],["D","HSM"]],"correct":"C"},{"num":233,"text":"A security administrator documented the following records during an assessment of network services:\n\nTwo weeks later, the administrator performed a log review and noticed the records were changed as\nfollows:\n\nWhen consulting the service owner, the administrator validated that the new address was not part of the\ncompany network. Which of the following was the company most likely experiencing?","options":[["A","DDoS attack"],["B","DNS poisoning"],["C","Ransomware compromise"],["D","Spyware infection"]],"correct":"B"},{"num":234,"text":"Which of the following is the primary reason why false negatives on a vulnerability scan should be a\nconcern?","options":[["A","The system has vulnerabilities that are not being detected."],["B","The time to remediate vulnerabilities that do not exist is excessive."],["C","Vulnerabilities with a lower severity will be prioritized over critical vulnerabilities."],["D","The system has vulnerabilities, and a patch has not yet been released."]],"correct":"A"},{"num":235,"text":"A company is concerned about theft of client data from decommissioned laptops. Which of the following is\nthe most cost-effective method to decrease this risk?","options":[["A","Wiping"],["B","Recycling"],["C","Shredding"],["D","Deletion"]],"correct":"A"},{"num":236,"text":"A company that has a large IT operation is looking to better control, standardize, and lower the time\nrequired to build new servers. Which of the following architectures will best achieve the company\u2019s\nobjectives?","options":[["A","IoT"],["B","IaC"],["C","IaaS"],["D","ICS"]],"correct":"B"},{"num":237,"text":"A government official receives a blank envelope containing photos and a note instructing the official to wire\na large sum of money by midnight to prevent the photos from being leaked on the internet. Which of the\nfollowing best describes the threat actor's intent?","options":[["A","Organized crime"],["B","Philosophical beliefs"],["C","Espionage"],["D","Blackmail"]],"correct":"D"},{"num":238,"text":"Which of the following is the best security reason for closing service ports that are not needed?","options":[["A","To mitigate risks associated with unencrypted traffic"],["B","To eliminate false positives from a vulnerability scan"],["C","To reduce a system's attack surface"],["D","To improve a system's resource utilization"]],"correct":"C"},{"num":239,"text":"Which of the following would a security administrator use to comply with a secure baseline during a patch\nupdate?","options":[["A","Information security policy"],["B","Service-level expectations"],["C","Standard operating procedure"],["D","Test result report"]],"correct":"C"},{"num":240,"text":"A malicious actor conducted a brute-force attack on a company's web servers and eventually gained\naccess to the company's customer information database. Which of the following is the most effective way to\nprevent similar attacks?","options":[["A","Regular patching of servers"],["B","Web application firewalls"],["C","Multifactor authentication"],["D","Enabling encryption of customer data"]],"correct":"C"},{"num":241,"text":"Which of the following options will provide the lowest RTO and RPO for a database?","options":[["A","Snapshots"],["B","On-site backups"],["C","Journaling"],["D","Hot site"]],"correct":"C"},{"num":242,"text":"Which of the following is a possible consequence of a VM escape?","options":[["A","Malicious instructions can be inserted into memory and give the attacker elevated permissions."],["B","An attacker can access the hypervisor and compromise other VMs."],["C","Unencrypted data can be read by a user who is in a separate environment."],["D","Users can install software that is not on the manufacturer\u2019s approved list."]],"correct":"B"},{"num":243,"text":"A security team at a large, global company needs to reduce the cost of storing data used for performing\ninvestigations. Which of the following types of data should have its retention length reduced?","options":[["A","Packet capture"],["B","Endpoint logs"],["C","OS security logs"],["D","Vulnerability scan"]],"correct":"A"},{"num":244,"text":"Which of the following is a type of vulnerability that involves inserting scripts into web-based applications in\norder to take control of the client's web browser?","options":[["A","SQL injection"],["B","Cross-site scripting"],["C","Zero-day exploit"],["D","On-path attack"]],"correct":"B"},{"num":245,"text":"While investigating a possible incident, a security analyst discovers the following:\n\nWhich of the following should the analyst do first?","options":[["A","Implement a WAF."],["B","Disable the query.php script."],["C","Block brute-force attempts on temporary users."],["D","Check the users table for new accounts."]],"correct":"D"},{"num":246,"text":"Due to a cyberattack, a company's IT systems were not operational for an extended period of time. The\ncompany wants to measure how quickly the systems must be restored in order to minimize business\ndisruption. Which of the following would the company most likely use?","options":[["A","Recovery point objective"],["B","Risk appetite"],["C","Risk tolerance"],["D","Recovery time objective"],["E","Mean time between failure"]],"correct":"D"},{"num":247,"text":"Which of the following actors attacking an organization is the most likely to be motivated by personal\nbeliefs?","options":[["A","Nation-state"],["B","Organized crime"],["C","Hacktivist"],["D","Insider threat"]],"correct":"C"},{"num":248,"text":"Which of the following should a security team use to document persistent vulnerabilities with related\nrecommendations?","options":[["A","Audit report"],["B","Risk register"],["C","Compliance report"],["D","Penetration test"]],"correct":"B"},{"num":249,"text":"An organization purchased a critical business application containing sensitive data. The organization would\nlike to ensure that the application is not exploited by common data exfiltration attacks. Which of the\nfollowing approaches would best help to fulfill this requirement?","options":[["A","URL scanning"],["B","WAF"],["C","Reverse proxy"],["D","NAC"]],"correct":"B"},{"num":250,"text":"A company wants to improve the availability of its application with a solution that requires minimal effort in\nthe event a server needs to be replaced or added. Which of the following would be the best solution to meet\nthese objectives?","options":[["A","Load balancing"],["B","Fault tolerance"],["C","Proxy servers"],["D","Replication"]],"correct":"A"},{"num":251,"text":"A company is performing a risk assessment on new software the company plans to use. Which of the\nfollowing should the company assess during this process?","options":[["A","Software vulnerabilities"],["B","Cost-benefit analysis"],["C","Ongoing monitoring strategies"],["D","Network infrastructure compatibility"]],"correct":"A"},{"num":252,"text":"A malicious actor is trying to access sensitive financial information from a company's database by\nintercepting and reusing log-in credentials. Which of the following attacks is the malicious actor attempting?","options":[["A","SQL injection"],["B","On-path"],["C","Brute-force"],["D","Password spraying"]],"correct":"B"},{"num":253,"text":"A new employee accessed an unauthorized website. An investigation found that the employee violated the\ncompany's rules. Which of the following did the employee violate?","options":[["A","MOU"],["B","AUP"],["C","NDA"],["D","MOA"]],"correct":"B"},{"num":254,"text":"A systems administrator is reviewing the VPN logs and notices that during non-working hours a user is\naccessing the company file server and information is being transferred to a suspicious IP address. Which of\nthe following threats is most likely occurring?","options":[["A","Typosquatting"],["B","Root or trust"],["C","Data exfiltration"],["D","Blackmail"]],"correct":"C"},{"num":256,"text":"A company discovers suspicious transactions that were entered into the company's database and attached\nto a user account that was created as a trap for malicious activity. Which of the following is the user account\nan example of?","options":[["A","Honeytoken"],["B","Honeynet"],["C","Honeypot"],["D","Honeyfile"]],"correct":"A"},{"num":257,"text":"A network engineer is increasing the overall security of network devices and needs to harden the devices.\nWhich of the following will best accomplish this task?","options":[["A","Configuring centralized logging"],["B","Generating local administrator accounts"],["C","Replacing Telnet with SSH"],["D","Enabling HTTP administration"]],"correct":"C"},{"num":258,"text":"A company's accounting department receives an urgent payment message from the company's bank\ndomain with instructions to wire transfer funds. The sender requests that the transfer be completed as soon\nas possible. Which of the following attacks is described?","options":[["A","Business email compromise"],["B","Vishing"],["C","Spear phishing"],["D","Impersonation"]],"correct":"A"},{"num":259,"text":"A company filed a complaint with its IT service provider after the company discovered the service provider's\nexternal audit team had access to some of the company's confidential information. Which of the following is\nthe most likely reason the company filed the complaint?","options":[["A","The MOU had basic clauses from a template."],["B","A SOW had not been agreed to by the client."],["C","A WO had not been mutually approved."],["D","A required NDA had not been signed."]],"correct":"D"},{"num":260,"text":"Which of the following aspects of the data management life cycle is most directly impacted by local and\ninternational regulations?","options":[["A","Destruction"],["B","Certification"],["C","Retention"],["D","Sanitization"]],"correct":"C"},{"num":261,"text":"An analyst is reviewing job postings to ensure sensitive company information is not being shared with the\ngeneral public. Which of the following is the analyst most likely looking for?","options":[["A","Office addresses"],["B","Software versions"],["C","List of board members"],["D","Government identification numbers"]],"correct":"B"},{"num":262,"text":"An engineer has ensured that the switches are using the latest OS, the servers have the latest patches, and\nthe endpoints' definitions are up to date. Which of the following will these actions most effectively prevent?","options":[["A","Zero-day attacks"],["B","Insider threats"],["C","End-of-life support"],["D","Known exploits"]],"correct":"D"},{"num":263,"text":"Which of the following is most likely a security concern when installing and using low-cost IoT devices in\ninfrastructure environments?","options":[["A","Country of origin"],["B","Device responsiveness"],["C","Ease of deployment"],["D","Storage of data"]],"correct":"D"},{"num":264,"text":"A company captures log-in details and reviews them each week to identify conditions such as excessive\nlog-in attempts and frequent lockouts. Which of the following should a security analyst recommend to\nimprove security compliance monitoring?","options":[["A","Including the date and person who reviewed the information in a report"],["B","Adding automated alerting when anomalies occur"],["C","Requiring a statement each week that no exceptions were noted"],["D","Masking the username in a report to protect privacy"]],"correct":"B"},{"num":265,"text":"A security team is in the process of hardening the network against externally crafted malicious packets.\nWhich of the following is the most secure method to protect the internal network?","options":[["A","Anti-malware solutions"],["B","Host-based firewalls"],["C","Intrusion prevention systems"],["D","Network access control"],["E","Network allow list"]],"correct":"C"},{"num":266,"text":"Which of the following is the best way to prevent an unauthorized user from plugging a laptop into an\nemployee's phone network port and then using tools to scan for database servers?","options":[["A","MAC filtering"],["B","Segmentation"],["C","Certification"],["D","Isolation"]],"correct":"B"},{"num":267,"text":"Which of the following should a systems administrator use to decrease the company's hardware attack\nsurface?","options":[["A","Replication"],["B","Isolation"],["C","Centralization"],["D","Virtualization"]],"correct":"B"},{"num":268,"text":"A company wants to add an MFA solution for all employees who access the corporate network remotely.\nLog-in requirements include something you know, are, and have. The company wants a solution that does\nnot require purchasing third-party applications or specialized hardware. Which of the following MFA\nsolutions would best meet the company's requirements?","options":[["A","Smart card with PIN and password"],["B","Security questions and a one-time passcode sent via email"],["C","Voice and fingerprint verification with an SMS one-time passcode"],["D","Mobile application-generated, one-time passcode with facial recognition"]],"correct":"B"},{"num":269,"text":"A company is using a legacy FTP server to transfer financial data to a third party. The legacy system does\nnot support SFTP, so a compensating control is needed to protect the sensitive, financial data in transit.\nWhich of the following would be the most appropriate for the company to use?","options":[["A","Telnet connection"],["B","SSH tunneling"],["C","Patch installation"],["D","Full disk encryption"]],"correct":"B"},{"num":270,"text":"A security manager wants to reduce the number of steps required to identify and contain basic threats.\nWhich of the following will help achieve this goal?","options":[["A","SOAR"],["B","SIEM"],["C","DMARC"],["D","NIDS"]],"correct":"A"},{"num":271,"text":"The Chief Information Officer (CIO) asked a vendor to provide documentation detailing the specific\nobjectives within the compliance framework that the vendor's services meet. The vendor provided a report\nand a signed letter stating that the services meet 17 of the 21 objectives. Which of the following did the\nvendor provide to the CIO?","options":[["A","Penetration test results"],["B","Self-assessment findings"],["C","Attestation of compliance"],["D","Third-party audit report"]],"correct":"C"},{"num":272,"text":"Which of the following describes the most effective way to address OS vulnerabilities after they are\nidentified?","options":[["A","Endpoint protection"],["B","Removal of unnecessary software"],["C","Configuration enforcement"],["D","Patching"]],"correct":"D"},{"num":273,"text":"The management team reports that employees are missing features on company-provided tablets, which is\ncausing productivity issues. The management team directs the IT team to resolve the issue within 48 hours.\nWhich of the following would be the best solution for the IT team to leverage in this scenario?","options":[["A","EDR"],["B","COPE"],["C","MDM"],["D","FDE"]],"correct":"C"},{"num":274,"text":"A company is implementing a policy to allow employees to use their personal equipment for work. However,\nthe company wants to ensure that only company-approved applications can be installed. Which of the\nfollowing addresses this concern?","options":[["A","MDM"],["B","Containerization"],["C","DLP"],["D","FIM"]],"correct":"A"},{"num":275,"text":"An alert references attacks associated with a zero-day exploit. An analyst places a bastion host in the\nnetwork to reduce the risk of the exploit. Which of the following types of controls is the analyst\nimplementing?","options":[["A","Compensating"],["B","Detective"],["C","Operational"],["D","Physical"]],"correct":"A"},{"num":276,"text":"A penetration test has demonstrated that domain administrator accounts were vulnerable to pass-the-hash\nattacks. Which of the following would have been the best strategy to prevent the threat actor from using\ndomain administrator accounts?","options":[["A","Audit each domain administrator account weekly for password compliance."],["B","Implement a privileged access management solution."],["C","Create IDS policies to monitor domain controller access."],["D","Use Group Policy to enforce password expiration."]],"correct":"B"},{"num":277,"text":"Which of the following is an example of memory injection?","options":[["A","Two processes access the same variable, allowing one to cause a privilege escalation."],["B","A process receives an unexpected amount of data, which causes malicious code to be executed."],["C","Malicious code is copied to the allocated space of an already running process."],["D","An executable is overwritten on the disk, and malicious code runs the next time it is executed."]],"correct":"C"},{"num":278,"text":"A security administrator is implementing encryption on all hard drives in an organization. Which of the\nfollowing security concepts is the administrator applying?","options":[["A","Integrity"],["B","Authentication"],["C","Zero Trust"],["D","Confidentiality"]],"correct":"D"},{"num":279,"text":"An administrator has configured a quarantine subnet for all guest devices that connect to the network.\nWhich of the following would be best for the security team to perform before allowing access to corporate\nresources?","options":[["A","Device fingerprinting"],["B","Compliance attestation"],["C","Penetration test"],["D","Application vulnerability test"]],"correct":"B"},{"num":280,"text":"A customer has a contract with a CSP and wants to identify which controls should be implemented in the\nIaaS enclave. Which of the following is most likely to contain this information?","options":[["A","Statement of work"],["B","Responsibility matrix"],["C","Service-level agreement"],["D","Master service agreement"]],"correct":"B"},{"num":281,"text":"A Chief Information Security Officer is developing procedures to guide detective and corrective activities\nassociated with common threats, including phishing, social engineering, and business email compromise.\nWhich of the following documents would be most relevant to revise as part of this process?","options":[["A","SDLC"],["B","IRP"],["C","BCP"],["D","AUP"]],"correct":"B"},{"num":282,"text":"Which of the following testing techniques uses both defensive and offensive testing methodologies with\ndevelopers to securely build key applications and software?","options":[["A","Blue"],["B","Yellow"],["C","Red"],["D","Green"]],"correct":"B"},{"num":283,"text":"An administrator wants to automate an account permissions update for a large number of accounts. Which\nof the following would best accomplish this task?","options":[["A","Security groups"],["B","Federation"],["C","User provisioning"],["D","Vertical scaling"]],"correct":"A"},{"num":284,"text":"Which of the following is the fastest and most cost-effective way to confirm a third-party supplier's\ncompliance with security obligations?","options":[["A","Attestation report"],["B","Third-party audit"],["C","Vulnerability assessment"],["D","Penetration testing"]],"correct":"A"},{"num":285,"text":"Various company stakeholders meet to discuss roles and responsibilities in the event of a security breach\nthat would affect offshore offices. Which of the following is this an example of?","options":[["A","Tabletop exercise"],["B","Penetration test"],["C","Geographic dispersion"],["D","Incident response"]],"correct":"A"},{"num":286,"text":"Which of the following is an example of a data protection strategy that uses tokenization?","options":[["A","Encrypting databases containing sensitive data"],["B","Replacing sensitive data with surrogate values"],["C","Removing sensitive data from production systems"],["D","Hashing sensitive data in critical systems"]],"correct":"B"},{"num":287,"text":"Which of the following is a type of vulnerability that refers to the unauthorized installation of applications on\na device through means other than the official application store?","options":[["A","Cross-site scripting"],["B","Buffer overflow"],["C","Jailbreaking"],["D","Side loading"]],"correct":"D"},{"num":288,"text":"Which of the following types of identification methods can be performed on a deployed application during\nruntime?","options":[["A","Dynamic analysis"],["B","Code review"],["C","Package monitoring"],["D","Bug bounty"]],"correct":"A"},{"num":289,"text":"Which of the following cryptographic solutions is used to hide the fact that communication is occurring?","options":[["A","Steganography"],["B","Data masking"],["C","Tokenization"],["D","Private key"]],"correct":"A"},{"num":290,"text":"Which of the following steps should be taken before mitigating a vulnerability in a production server?","options":[["A","Escalate the issue to the SDLC team."],["B","Use the IR plan to evaluate the changes."],["C","Perform a risk assessment to classify the vulnerability."],["D","Refer to the change management policy."]],"correct":"D"},{"num":291,"text":"A security engineer needs to quickly identify a signature from a known malicious file. Which of the following\nanalysis methods would the security engineer most likely use?","options":[["A","Static"],["B","Sandbox"],["C","Network traffic"],["D","Package monitoring"]],"correct":"A"},{"num":292,"text":"Which of the following should a company use to provide proof of external network security testing?","options":[["A","Business impact analysis"],["B","Supply chain analysis"],["C","Vulnerability assessment"],["D","Third-party attestation"]],"correct":"D"},{"num":293,"text":"A security administrator is addressing an issue with a legacy system that communicates data using an\nunencrypted protocol to transfer sensitive data to a third party. No software updates that use an encrypted\nprotocol are available, so a compensating control is needed. Which of the following are the most\nappropriate for the administrator to suggest? (Choose two.)","options":[["A","Tokenization"],["B","Cryptographic downgrade"],["C","SSH tunneling"],["D","Segmentation"],["E","Patch installation"],["F","Data masking"]],"correct":"AC"},{"num":294,"text":"Which of the following steps in the risk management process involves establishing the scope and potential\nrisks involved with a project?","options":[["A","Risk assessment"],["B","Risk identification"],["C","Risk treatment"],["D","Risk monitoring and review"]],"correct":"B"},{"num":295,"text":"A company's website is www.company.com. Attackers purchased the domain www.c0mpany.com. Which\nof the following types of attacks describes this example?","options":[["A","Typosquatting"],["B","Brand impersonation"],["C","On-path"],["D","Watering-hole"]],"correct":"A"},{"num":296,"text":"Which of the following allows a systems administrator to tune permissions for a file?","options":[["A","Patching"],["B","Access control list"],["C","Configuration enforcement"],["D","Least privilege"]],"correct":"B"},{"num":297,"text":"Which of the following would be the greatest concern for a company that is aware of the consequences of\nnon-compliance with government regulations?","options":[["A","Right to be forgotten"],["B","Sanctions"],["C","External compliance reporting"],["D","Attestation"]],"correct":"B"},{"num":298,"text":"Which of the following security concepts is accomplished when granting access after an individual has\nlogged into a computer network?","options":[["A","Authorization"],["B","Identification"],["C","Non-repudiation"],["D","Authentication"]],"correct":"A"},{"num":299,"text":"A growing organization, which hosts an externally accessible application, adds multiple virtual servers to\nimprove application performance and decrease the resource usage on individual servers. Which of the\nfollowing solutions is the organization most likely to employ to further increase performance and availability?","options":[["A","Load balancer"],["B","Jump server"],["C","Proxy server"],["D","SD-WAN"]],"correct":"A"},{"num":300,"text":"A systems administrator is concerned users are accessing emails through a duplicate site that is not run by\nthe company. Which of the following is used in this scenario?","options":[["A","Impersonation"],["B","Replication"],["C","Phishing"],["D","Smishing"]],"correct":"C"},{"num":301,"text":"A security engineer at a large company needs to enhance IAM in order to ensure that employees can only\naccess corporate systems during their shifts. Which of the following access controls should the security\nengineer implement?","options":[["A","Role-based"],["B","Time-of-day restrictions"],["C","Least privilege"],["D","Biometric authentication"]],"correct":"B"},{"num":302,"text":"A company wants to ensure employees are allowed to copy files from a virtual desktop during the workday\nbut are restricted during non-working hours. Which of the following security measures should the company\nset up?","options":[["A","Digital rights management"],["B","Role-based access control"],["C","Time-based access control"],["D","Network access control"]],"correct":"C"},{"num":303,"text":"Employees sign an agreement that restricts specific activities when leaving the company. Violating the\nagreement can result in legal consequences. Which of the following agreements does this best describe?","options":[["A","SLA"],["B","BPA"],["C","NDA"],["D","MOA"]],"correct":"C"},{"num":304,"text":"A systems administrator just purchased multiple network devices. Which of the following should the\nsystems administrator perform to prevent attackers from accessing the devices by using publicly available\ninformation?","options":[["A","Install endpoint protection."],["B","Disable ports/protocols."],["C","Change default passwords."],["D","Remove unnecessary software."]],"correct":"C"},{"num":305,"text":"A CVE in a key back-end component of an application has been disclosed. The systems administrator is\nidentifying all of the systems in the environment that are susceptible to this risk. Which of the following\nshould the systems administrator perform?","options":[["A","Packet capture"],["B","Vulnerability scan"],["C","Metadata analysis"],["D","Automated reporting"]],"correct":"B"},{"num":306,"text":"Which of the following activities uses OSINT?","options":[["A","Social engineering testing"],["B","Data analysis of logs"],["C","Collecting evidence of malicious activity"],["D","Producing IOC for malicious artifacts"]],"correct":"A"},{"num":307,"text":"Which of the following are the best security controls for controlling on-premises access? (Choose two.)","options":[["A","Swipe card"],["B","Picture ID"],["C","Phone authentication application"],["D","Biometric scanner"],["E","Camera"],["F","Memorable question"]],"correct":"AD"},{"num":308,"text":"A company is considering an expansion of access controls for an application that contractors and internal\nemployees use to reduce costs. Which of the following risk elements should the implementation team\nunderstand before granting access to the application?","options":[["A","Threshold"],["B","Appetite"],["C","Avoidance"],["D","Register"]],"correct":"B"},{"num":309,"text":"Which of the following is the act of proving to a customer that software developers are trained on secure\ncoding?","options":[["A","Assurance"],["B","Contract"],["C","Due diligence"],["D","Attestation"]],"correct":"D"},{"num":310,"text":"An administrator is creating a secure method for a contractor to access a test environment. Which of the\nfollowing would provide the contractor with the best access to the test environment?","options":[["A","Application server"],["B","Jump server"],["C","RDP server"],["D","Proxy server"]],"correct":"B"},{"num":311,"text":"A security analyst notices unusual behavior on the network. The IDS on the network was not able to detect\nthe activities. Which of the following should the security analyst use to help the IDS detect such attacks in\nthe future?","options":[["A","Signatures"],["B","Trends"],["C","Honeypot"],["D","Reputation"]],"correct":"A"},{"num":312,"text":"To which of the following security categories does an EDR solution belong?","options":[["A","Physical"],["B","Operational"],["C","Managerial"],["D","Technical"]],"correct":"D"},{"num":313,"text":"A company relies on open-source software libraries to build the software used by its customers. Which of\nthe following vulnerability types would be the most difficult to remediate due to the company\u2019s reliance on\nopen-source libraries?","options":[["A","Buffer overflow"],["B","SQL injection"],["C","Cross-site scripting"],["D","Zero-day"]],"correct":"D"},{"num":314,"text":"An organization has a new regulatory requirement to implement corrective controls on a financial system.\nWhich of the following is the most likely reason for the new requirement?","options":[["A","To defend against insider threats altering banking details"],["B","To ensure that errors are not passed to other systems"],["C","To allow for business insurance to be purchased"],["D","To prevent unauthorized changes to financial data"]],"correct":"B"},{"num":315,"text":"Which of the following is the stage in an investigating when forensic images are obtained?","options":[["A","Acquisition"],["B","Preservation"],["C","Reporting"],["D","E-discovery"]],"correct":"A"},{"num":316,"text":"Which of the following describes the difference between encryption and hashing?","options":[["A","Encryption protects data in transit, while hashing protects data at rest."],["B","Encryption replaces cleartext with ciphertext, while hashing calculates a checksum."],["C","Encryption ensures data integrity, while hashing ensures data confidentiality."],["D","Encryption uses a public-key exchange, while hashing uses a private key."]],"correct":"B"},{"num":317,"text":"A security report shows that during a two-week test period, 80% of employees unwittingly disclosed their\nSSO credentials when accessing an external website. The organization purposely created the website to\nsimulate a cost-free password complexity test. Which of the following would best help reduce the number\nof visits to similar websites in the future?","options":[["A","Block all outbound traffic from the intranet."],["B","Introduce a campaign to recognize phishing attempts."],["C","Restrict internet access for the employees who disclosed credentials."],["D","Implement a deny list of websites."]],"correct":"B"},{"num":318,"text":"A Chief Information Security Officer (CISO) has developed information security policies that relate to the\nsoftware development methodology. Which of the following would the CISO most likely include in the\norganization\u2019s documentation?","options":[["A","Peer review requirements"],["B","Multifactor authentication"],["C","Branch protection tests"],["D","Secrets management configurations"]],"correct":"A"},{"num":319,"text":"An organization is developing a security program that conveys the responsibilities associated with the\ngeneral operation of systems and software within the organization. Which of the following documents would\nmost likely communicate these expectations?","options":[["A","Business continuity plan"],["B","Change management procedure"],["C","Acceptable use policy"],["D","Software development life cycle policy"]],"correct":"C"},{"num":320,"text":"A security analyst created a fake account and saved the password in a non-readily accessible directory in a\nspreadsheet. An alert was also configured to notify the security team if the spreadsheet is opened. Which of\nthe following best describes the deception method being deployed?","options":[["A","Honeypot"],["B","Honeyfile"],["C","Honeytoken"],["D","Honeynet"]],"correct":"B"},{"num":321,"text":"Which of the following is the best way to provide secure, remote access for employees while minimizing the\nexposure of a company\u2019s internal network?","options":[["A","VPN"],["B","LDAP"],["C","FTP"],["D","RADIUS"]],"correct":"A"},{"num":322,"text":"A company wants to track modifications to the code that is used to build new virtual servers. Which of the\nfollowing will the company most likely deploy?","options":[["A","Change management ticketing system"],["B","Behavioral analyzer"],["C","Collaboration platform"],["D","Version control tool"]],"correct":"D"},{"num":323,"text":"Which of the following documents details how to accomplish a technical security task?","options":[["A","Standard"],["B","Policy"],["C","Guideline"],["D","Procedure"]],"correct":"D"},{"num":324,"text":"While conducting a business continuity tabletop exercise, the security team becomes concerned by\npotential impact if a generator was to develop a fault during failover. Which of the following is the team\nmost likely to consider in regard to risk management activities?","options":[["A","RPO"],["B","ARO"],["C","BIA"],["D","MTTR"]],"correct":"C"},{"num":325,"text":"Which of the following is prevented by proper data sanitization?","options":[["A","Hackers\u2019 ability to obtain data from used hard drives"],["B","Devices reaching end-of-life and losing support"],["C","Disclosure of sensitive data through incorrect classification"],["D","Incorrect inventory data leading to a laptop shortage"]],"correct":"A"},{"num":326,"text":"A certificate authority needs to post information about expired certificates. Which of the following would\naccomplish this task?","options":[["A","TPM"],["B","CRL"],["C","PKI"],["D","CSR"]],"correct":"B"},{"num":327,"text":"Which of the following can best contribute to prioritizing patch applications?","options":[["A","CVSS"],["B","SCAP"],["C","OSINT"],["D","CVE"]],"correct":"A"},{"num":328,"text":"A systems administrator creates a script that validates OS version, patch levels, and installed applications\nwhen users log in. Which of the following examples best describes the purpose of this script?","options":[["A","Resource scaling"],["B","Policy enumeration"],["C","Baseline enforcement"],["D","Guard rails implementation"]],"correct":"C"},{"num":329,"text":"A security analyst learns that an attack vector, which was used as a part of a recent incident, was a wellknown IoT device exploit. The analyst needs to review logs to identify the time of initial exploit. Which of the\nfollowing logs should the analyst review first?","options":[["A","Endpoint"],["B","Application"],["C","Firewall"],["D","NAC"]],"correct":"C"},{"num":330,"text":"A company\u2019s gate access logs show multiple entries from an employee\u2019s ID badge within a two-minute\nperiod. Which of the following is this an example of?","options":[["A","RFID cloning"],["B","Side-channel attack"],["C","Shoulder surfing"],["D","Tailgating"]],"correct":"A"},{"num":331,"text":"Which of the following most accurately describes the order in which a security engineer should implement\nsecure baselines?","options":[["A","Deploy, maintain, establish"],["B","Establish, maintain, deploy"],["C","Establish, deploy, maintain"],["D","Deploy, establish, maintain"]],"correct":"C"},{"num":332,"text":"A SOC analyst establishes a remote control session on an end user\u2019s machine and discovers the following\nin a file:\ngmail.com[ENT]my.name@gmail.com[ENT]NoOneCanGuessThis123! [ENT]Hello Susan, it\nwas great to see you the other day! Let's plan a followup[BACKSPACE]follow-up\nmeeting soon. Here is the link to register. [RTN][CTRL]c [CTRL]v [RTN]after\n[BACKSPACE]After you register give me a call on my cellphone.\nWhich of the following actions should the SOC analyst perform first?","options":[["A","Advise the user to change passwords."],["B","Reimage the end user\u2019s machine."],["C","Check the policy on personal email at work."],["D","Check host firewall logs."]],"correct":"A"},{"num":333,"text":"Which of the following is a reason environmental variables are a concern when reviewing potential system\nvulnerabilities?","options":[["A","The contents of environmental variables could affect the scope and impact of an exploited vulnerability."],["B","In-memory environmental variable values can be overwritten and used by attackers to insert malicious"],["C","Environmental variables define cryptographic standards for the system and could create vulnerabilities if"],["D","Environmental variables will determine when updates are run and could mitigate the likelihood of"]],"correct":"A"},{"num":334,"text":"A company evaluates several options that would allow employees to have remote access to the network.\nThe security team wants to ensure the solution includes AAA to comply with internal security policies.\nWhich of the following should the security team recommend?","options":[["A","IPSec with RADIUS"],["B","RDP connection with LDAPS"],["C","Web proxy for all remote traffic"],["D","Jump server with 802.1X"]],"correct":"A"},{"num":335,"text":"An administrator must replace an expired SSL certificate. Which of the following does the administrator\nneed to create the new SSL certificate?","options":[["A","CSR"],["B","OCSP"],["C","Key"],["D","CRL"]],"correct":"A"},{"num":336,"text":"A systems administrator receives a text message from an unknown number claiming to be the Chief\nExecutive Officer of the company. The message states an emergency situation requires a password reset.\nWhich of the following threat vectors is being used?","options":[["A","Typosquatting"],["B","Smishing"],["C","Pretexting"],["D","Impersonation"]],"correct":"B"},{"num":337,"text":"A Chief Information Security Officer (CISO) wants to:\nPrevent employees from downloading malicious content.\nEstablish controls based on departments and users.\nMap internet access for business applications to specific service accounts.\nRestrict content based on categorization.\nWhich of the following should the CSO implement?","options":[["A","Web application firewall"],["B","Secure DNS server"],["C","Jump server"],["D","Next-generation firewall"]],"correct":"D"},{"num":338,"text":"A company is aware of a given security risk related to a specific market segment. The business chooses\nnot to accept responsibility and target their services to a different market segment. Which of the following\ndescribes this risk management strategy?","options":[["A","Exemption"],["B","Exception"],["C","Avoid"],["D","Transfer"]],"correct":"C"},{"num":339,"text":"A security analyst needs to improve the company\u2019s authentication policy following a password audit. Which\nof the following should be included in the policy? (Choose two.)","options":[["A","Length"],["B","Complexity"],["C","Least privilege"],["D","Something you have"],["E","Security keys"],["F","Biometrics"]],"correct":"AB"},{"num":340,"text":"Which of the following is an example of a treatment strategy for a continuous risk?","options":[["A","Email gateway to block phishing attempts"],["B","Background checks for new employees"],["C","Dual control requirements for wire transfers"],["D","Branch protection as part of the CI/CD pipeline"]],"correct":"A"},{"num":341,"text":"An organization wants to deploy software in a container environment to increase security. Which of the\nfollowing would limit the organization's ability to achieve this goal?","options":[["A","Regulatory compliance"],["B","Patch availability"],["C","Kernel version"],["D","Monolithic code"]],"correct":"D"},{"num":342,"text":"Prior to implementing a design change, the change must go through multiple steps to ensure that it does\nnot cause any security issues. Which of the following is most likely to be one of those steps?","options":[["A","Board review"],["B","Service restart"],["C","Backout planning"],["D","Maintenance"]],"correct":"C"},{"num":343,"text":"The internal audit team determines a software application is no longer in scope for external reporting\nrequirements. Which of the following will confirm that the application is no longer applicable?","options":[["A","Data inventory and retention"],["B","Right to be forgotten"],["C","Due care and due diligence"],["D","Acknowledgement and attestation"]],"correct":"A"},{"num":344,"text":"Which of the following are the first steps an analyst should perform when developing a heat map? (Choose\ntwo.)","options":[["A","Methodically walk around the office noting Wi-Fi signal strength."],["B","Log in to each access point and check the settings."],["C","Create or obtain a layout of the office."],["D","Measure cable lengths between access points."],["E","Review access logs to determine the most active devices."],["F","Remove possible impediments to radio transmissions."]],"correct":"AC"},{"num":345,"text":"Which of the following is used to improve security and overall functionality without losing critical application\ndata?","options":[["A","Reformatting"],["B","Decommissioning"],["C","Patching"],["D","Encryption"]],"correct":"C"},{"num":346,"text":"An organization is preparing to export proprietary software to a customer. Which of the following would be\nthe best way to prevent the loss of intellectual property?","options":[["A","Code signing"],["B","Obfuscation"],["C","Tokenization"],["D","Blockchain"]],"correct":"B"},{"num":347,"text":"Which of the following should be used to ensure a device is inaccessible to a network-connected resource?","options":[["A","Disablement of unused services"],["B","Web application firewall"],["C","Host isolation"],["D","Network-based IDS"]],"correct":"C"},{"num":348,"text":"In which of the following will unencrypted network traffic most likely be found?","options":[["A","SDN"],["B","IoT"],["C","VPN"],["D","SCADA"]],"correct":"D"},{"num":349,"text":"Which of the following is the best reason to perform a tabletop exercise?","options":[["A","To address audit findings"],["B","To collect remediation response times"],["C","To update the IRP"],["D","To calculate the ROI"]],"correct":"C"},{"num":350,"text":"Which of the following is a use of CVSS?","options":[["A","To determine the cost associated with patching systems"],["B","To identify unused ports and services that should be closed"],["C","To analyze code for defects that could be exploited"],["D","To prioritize the remediation of vulnerabilities"]],"correct":"D"},{"num":351,"text":"For an upcoming product launch, a company hires a marketing agency whose owner is a close relative of\nthe Chief Executive Officer. Which of the following did the company violate?","options":[["A","Independent assessments"],["B","Supply chain analysis"],["C","Right-to-audit clause"],["D","Conflict of interest policy"]],"correct":"D"},{"num":352,"text":"An organization designs an inbound firewall with a fail-open configuration while implementing a website.\nWhich of the following would the organization consider to be the highest priority?","options":[["A","Confidentiality"],["B","Non-repudiation"],["C","Availability"],["D","Integrity"]],"correct":"C"},{"num":353,"text":"An engineer needs to ensure that a script has not been modified before it is launched. Which of the\nfollowing best provides this functionality?","options":[["A","Masking"],["B","Obfuscation"],["C","Hashing"],["D","Encryption"]],"correct":"C"},{"num":354,"text":"Which of the following is the most important element when defining effective security governance?","options":[["A","Discovering and documenting external considerations"],["B","Developing procedures for employee onboarding and offboarding"],["C","Assigning roles and responsibilities for owners, controllers, and custodians"],["D","Defining and monitoring change management procedures"]],"correct":"C"},{"num":355,"text":"A contractor is required to visually inspect the motherboards of all new servers that are purchased to\ndetermine whether the servers were tampered with. Which of the following risks is the contractor attempting\nto mitigate?","options":[["A","Embedded rootkit"],["B","Supply chain"],["C","Firmware failure"],["D","RFID keylogger"]],"correct":"B"},{"num":356,"text":"Which of the following could potentially be introduced at the time of side loading?","options":[["A","User impersonation"],["B","Rootkit"],["C","On-path attack"],["D","Buffer overflow"]],"correct":"B"},{"num":357,"text":"While a school district is performing state testing, a security analyst notices all internet services are\nunavailable. The analyst discovers that ARP poisoning is occurring on the network and then terminates\naccess for the host. Which of the following is most likely responsible for this malicious activity?","options":[["A","Unskilled attacker"],["B","Shadow IT"],["C","Insider threat"],["D","Nation-state"]],"correct":"C"},{"num":358,"text":"A user needs to complete training at https://comptiatraining.com. After manually entering the URL, the user\nsees that the accessed website is noticeably different from the standard company website. Which of the\nfollowing is the most likely explanation for the difference?","options":[["A","Cross-site scripting"],["B","Pretexting"],["C","Typosquatting"],["D","Vishing"]],"correct":"C"},{"num":359,"text":"A company has yearly engagements with a service provider. The general terms and conditions are the\nsame for all engagements. The company wants to simplify the process and revisit the general terms every\nthree years. Which of the following documents would provide the best way to set the general terms?","options":[["A","MSA"],["B","NDA"],["C","MOU"],["D","SLA"]],"correct":"A"},{"num":360,"text":"While updating the security awareness training, a security analyst wants to address issues created if\nvendors' email accounts are compromised. Which of the following recommendations should the security\nanalyst include in the training?","options":[["A","Refrain from clicking on images included in emails from new vendors"],["B","Delete emails from unknown service provider partners."],["C","Require that invoices be sent as attachments"],["D","Be alert to unexpected requests from familiar email addresses"]],"correct":"D"},{"num":361,"text":"A new corporate policy requires all staff to use multifactor authentication to access company resources.\nWhich of the following can be utilized to set up this form of identity and access management? (Choose\ntwo.)","options":[["A","Authentication tokens"],["B","Least privilege"],["C","Biometrics"],["D","LDAP"],["E","Password vaulting"],["F","SAML"]],"correct":"AC"},{"num":362,"text":"A help desk employee receives a call from someone impersonating the Chief Executive Officer. The caller\nasks for assistance with resetting a password. Which of the following best describes this event?","options":[["A","Vishing"],["B","Hacktivism"],["C","Blackmail"],["D","Misinformation"]],"correct":"A"},{"num":363,"text":"The number of tickets the help desk has been receiving has increased recently due to numerous falsepositive phishing reports. Which of the following would be best to help to reduce the false positives?","options":[["A","Performing more phishing simulation campaigns"],["B","Improving security awareness training"],["C","Hiring more help desk staff"],["D","Implementing an incident reporting web page"]],"correct":"B"},{"num":364,"text":"A systems administrator needs to encrypt all data on employee laptops. Which of the following encryption\nlevels should be implemented?","options":[["A","Volume"],["B","Partition"],["C","Full disk"],["D","File"]],"correct":"C"},{"num":365,"text":"Which of the following actions best addresses a vulnerability found on a company's web server?","options":[["A","Patching"],["B","Segmentation"],["C","Decommissioning"],["D","Monitoring"]],"correct":"A"},{"num":366,"text":"A company is changing its mobile device policy. The company has the following requirements:\nCompany-owned devices\nAbility to harden the devices\nReduced security risk\nCompatibility with company resources\nWhich of the following would best meet these requirements?","options":[["A","BYOD"],["B","CYOD"],["C","COPE"],["D","COBO"]],"correct":"C"},{"num":367,"text":"A company is concerned about employees unintentionally introducing malware into the network. The\ncompany identified fifty employees who clicked on a link embedded in an email sent by the internal IT\ndepartment. Which of the following should the company implement to best improve its security posture?","options":[["A","Social engineering training"],["B","SPF configuration"],["C","Simulated phishing campaign"],["D","Insider threat awareness"]],"correct":"C"},{"num":368,"text":"A penetration test identifies that an SMBv1 is enabled on multiple servers across an organization. The\norganization wants to remediate this vulnerability in the most efficient way possible. Which of the following\nshould the organization use for this purpose?","options":[["A","GPO"],["B","ACL"],["C","SFTP"],["D","DLP"]],"correct":"A"},{"num":369,"text":"Which of the following best protects sensitive data in transit across a geographically dispersed\ninfrastructure?","options":[["A","Encryption"],["B","Masking"],["C","Tokenization"],["D","Obfuscation"]],"correct":"A"},{"num":370,"text":"As part of new compliance audit requirements, multiple servers need to be segmented on different\nnetworks and should be reachable only from authorized internal systems. Which of the following would\nmeet the requirements?","options":[["A","Configure firewall rules to block external access to Internal resources."],["B","Set up a WAP to allow internal access from public networks."],["C","Implement a new IPSec tunnel from internal resources."],["D","Deploy an internal jump server to access resources."]],"correct":"A"},{"num":371,"text":"Which of the following activities should be performed first to compile a list of vulnerabilities in an\nenvironment?","options":[["A","Automated scanning"],["B","Penetration testing"],["C","Threat hunting"],["D","Log aggregation"],["E","Adversarial emulation"]],"correct":"A"},{"num":372,"text":"Which of the following can be used to mitigate attacks from high-risk regions?","options":[["A","Obfuscation"],["B","Data sovereignty"],["C","IP geolocation"],["D","Encryption"]],"correct":"C"},{"num":373,"text":"An organization that handles sensitive information wants to protect the information by using a reversible\ntechnology. Which of the following best satisfies this requirement?","options":[["A","Hardware security module"],["B","Hashing algorithm"],["C","Tokenization"],["D","Steganography"]],"correct":"C"},{"num":374,"text":"After a series of account compromises and credential misuse, a company hires a security manager to\ndevelop a security program. Which of the following steps should the security manager take first to increase\nsecurity awareness?","options":[["A","Evaluate tools that identify risky behavior and distribute reports on the findings."],["B","Send quarterly newsletters that explain the importance of password management."],["C","Develop phishing campaigns and notify the management team of any successes."],["D","Update policies and handbooks to ensure all employees are informed of the new procedures."]],"correct":"D"},{"num":375,"text":"A program manager wants to ensure contract employees can only access the company's computers\nMonday through Friday from 9 a m. to 5 p.m. Which of the following would best enforce this access control?","options":[["A","Creating a GPO for all contract employees and setting time-of-day log-in restrictions"],["B","Creating a discretionary access policy and setting rule-based access for contract employees"],["C","Implementing an OAuth server and then setting least privilege for contract employees"],["D","Implementing SAML with federation to the contract employees\u2019 authentication server"]],"correct":"A"},{"num":376,"text":"A recent power outage halted operations at a company's only data center. Which of the following solutions\nwould best prevent an event like this one in the future?","options":[["A","Platform diversity"],["B","Generator"],["C","Snapshots"],["D","Load balancing"]],"correct":"B"},{"num":377,"text":"Which of the following analysis methods allows an organization to measure the exposure factor associated\nwith organizational assets?","options":[["A","Heuristic"],["B","Quantitative"],["C","User-driven"],["D","Trend-based"]],"correct":"B"},{"num":378,"text":"A security analyst notices an increase in port scans on the edge of the corporate network. Which of the\nfollowing logs should the analyst check to obtain the attacker\u2019s source IP address?","options":[["A","OS security"],["B","Firewall"],["C","Application"],["D","Endpoint"]],"correct":"B"},{"num":379,"text":"A security team receives reports about high latency and complete network unavailability throughout most of\nthe office building. Flow logs from the campus switches show high traffic on TCP 445. Which of the\nfollowing is most likely the root cause of this incident?","options":[["A","Buffer overflow"],["B","NTP amplification attack"],["C","Worm"],["D","DoS attack"]],"correct":"C"},{"num":380,"text":"A security analyst is examining a penetration test report and notices that the tester pivoted to critical internal\nsystems with the same local user ID and password. Which of the following would help prevent this in the\nfuture?","options":[["A","Implement centralized authentication with proper password policies"],["B","Add password complexity rules and increase password history limits"],["C","Connect the systems to an external authentication server"],["D","Limit the ability of user accounts to change passwords"]],"correct":"A"},{"num":381,"text":"When used with an access control vestibule which of the following would provide the best prevention\nagainst tailgating?","options":[["A","PIN"],["B","Access card"],["C","Security guard"],["D","CCTV"]],"correct":"C"},{"num":382,"text":"A security professional discovers a folder that contains an employee's personal information located on the\nenterprise\u2019s shared drive. Which of the following best describes the data type the security professional\nshould use to identify organizational policies and standards concerning the storage of employees' personal\ninformation?","options":[["A","Legal"],["B","Financial"],["C","Privacy"],["D","Intellectual property"]],"correct":"C"},{"num":383,"text":"A site reliability engineer is designing a recovery strategy that requires quick failover to an identical site if\nthe primary facility goes down. Which of the following types of sites should the engineer consider?","options":[["A","Recovery site"],["B","Hot site"],["C","Cold site"],["D","Warm site"]],"correct":"B"},{"num":384,"text":"Which of the following would an organization most likely use to minimize the loss of data on a file server in\nthe event data needs to be restored?","options":[["A","Snapshots"],["B","Journaling"],["C","Obfuscation"],["D","Tokenization"]],"correct":"A"},{"num":385,"text":"Which of the following solutions would most likely be used in the financial industry to mask sensitive data?","options":[["A","Tokenization"],["B","Hashing"],["C","Salting"],["D","Steganography"]],"correct":"A"},{"num":386,"text":"Which of the following is a type of vulnerability that may result from outdated algorithms or keys?","options":[["A","Hash collision"],["B","Cryptographic"],["C","Buffer overflow"],["D","Input validation"]],"correct":"B"},{"num":387,"text":"A company wants to prevent proprietary and confidential company information from being shared to\noutsiders. Which of the following would this best describe?","options":[["A","MOA"],["B","SLA"],["C","MSA"],["D","NDA"]],"correct":"D"},{"num":388,"text":"A security administrator needs to reduce the attack surface in the company's data centers. Which of the\nfollowing should the security administrator do to complete this task?","options":[["A","Implement a honeynet."],["B","Define Group Policy on the servers."],["C","Configure the servers for high availability."],["D","Upgrade end-of-support operating systems."]],"correct":"D"},{"num":389,"text":"Which of the following is a prerequisite for a DLP solution?","options":[["A","Data destruction"],["B","Data sanitization"],["C","Data classification"],["D","Data masking"]],"correct":"C"},{"num":390,"text":"A business provides long-term cold storage services to banks that are required to follow regulator-imposed\ndata retention guidelines. Banks that use these services require that data is disposed of in a specific\nmanner at the conclusion of the regulatory threshold for data retention. Which of the following aspects of\ndata management is the most important to the bank in the destruction of this data?","options":[["A","Encryption"],["B","Classification"],["C","Certification"],["D","Procurement"]],"correct":"C"},{"num":391,"text":"The physical security team at a company receives reports that employees are not displaying their badges.\nThe team also observes employees tailgating at controlled entrances. Which of the following topics will the\nsecurity team most likely emphasize in upcoming security training?","options":[["A","Social engineering"],["B","Situational awareness"],["C","Phishing"],["D","Acceptable use policy"]],"correct":"B"},{"num":392,"text":"Which of the following would most likely be a hacktivist's motive?","options":[["A","Financial gain"],["B","Espionage"],["C","Philosophical beliefs"],["D","Revenge"]],"correct":"C"},{"num":393,"text":"During a recent log review, an analyst discovers evidence of successful injection attacks. Which of the\nfollowing will best address this issue?","options":[["A","Authentication"],["B","Secure cookies"],["C","Static code analysis"],["D","Input validation"]],"correct":"D"},{"num":394,"text":"Which of the following is the first step to secure a newly deployed server?","options":[["A","Close unnecessary service ports."],["B","Update the current version of the software."],["C","Add the device to the ACL."],["D","Upgrade the OS version."]],"correct":"B"},{"num":395,"text":"A security analyst receives an alert that there was an attempt to download known malware. Which of the\nfollowing actions would allow the best chance to analyze the malware?","options":[["A","Review the IPS logs and determine which command-and-control IPs were blocked."],["B","Analyze application logs to see how the malware attempted to maintain persistence."],["C","Run vulnerability scans to check for systems and applications that are vulnerable to the malware"],["D","Obtain and execute the malware in a sandbox environment and perform packet captures."]],"correct":"D"},{"num":396,"text":"Which of the following should be used to ensure a user has the permissions needed to effectively do an\nassigned job role?","options":[["A","Changing default passwords"],["B","Implementing least privilege"],["C","Enforcing baseline configurations"],["D","Applying network segmentation"]],"correct":"B"},{"num":397,"text":"An employee receives a text message from an unrecognized number claiming to be the Chief Executive\nOfficer and asking the employee to purchase gift cards. Which of the following types of attacks describes\nthis example?","options":[["A","Watering-hole"],["B","Disinformation"],["C","Phishing"],["D","Impersonation"]],"correct":"D"},{"num":398,"text":"An unexpected and out-of-character email message from a Chief Executive Officer's corporate account\nasked an employee to provide financial information and to change the recipient's contact number. Which of\nthe following attack vectors is most likely being used?","options":[["A","Business email compromise"],["B","Phishing"],["C","Brand impersonation"],["D","Pretexting"]],"correct":"A"},{"num":399,"text":"Which of the following should an organization use to ensure that it can review the controls and performance\nof a service provider or vendor?","options":[["A","Service-level agreement"],["B","Memorandum of agreement"],["C","Right-to-audit clause"],["D","Supply chain analysis"]],"correct":"C"},{"num":400,"text":"Which of the following is used to calculate the impact to an organization per cybersecurity incident?","options":[["A","SLE"],["B","ALE"],["C","ARO"],["D","SLA"]],"correct":"A"},{"num":401,"text":"A retail company receives a request to remove a customer's data. Which of the following is the retail\ncompany considered under GDPR legislation?","options":[["A","Data processor"],["B","Data controller"],["C","Data subject"],["D","Data custodian"]],"correct":"B"},{"num":402,"text":"An administrator implements web-filtering products but still sees that users are visiting malicious links.\nWhich of the following configuration items does the security administrator need to review?","options":[["A","Intrusion prevention system"],["B","Content categorization"],["C","Encryption"],["D","DNS service"]],"correct":"B"},{"num":403,"text":"A security analyst is reviewing the following logs about a suspicious activity alert for a user's VPN log-ins:\n\nWhich of the following malicious activity indicators triggered the alert?","options":[["A","Impossible travel"],["B","Account lockout"],["C","Blocked content"],["D","Concurrent session usage"]],"correct":"A"},{"num":404,"text":"Which of the following phases of the incident response process attempts to minimize disruption?","options":[["A","Recovery"],["B","Containment"],["C","Preparation"],["D","Analysis"]],"correct":"B"},{"num":405,"text":"Which of the following security principles most likely requires validation before allowing traffic between\nsystems?","options":[["A","Policy enforcement"],["B","Authentication"],["C","Zero Trust architecture"],["D","Confidentiality"]],"correct":"C"},{"num":406,"text":"Company A jointly develops a product with Company B, which is located in a different country. Company A\nfinds out that their intellectual property is being shared with unauthorized companies. Which of the following\nhas been breached?","options":[["A","SLA"],["B","AUP"],["C","SOW"],["D","MOA"]],"correct":"D"},{"num":407,"text":"An accounting employee recently used software that was not approved by the company. Which of the\nfollowing risks does this most likely represent?","options":[["A","Unskilled attacker"],["B","Hacktivist"],["C","Shadow IT"],["D","Supply chain"]],"correct":"C"},{"num":408,"text":"Which of the following activities is used to determine the reason an incident occurred, prior to closing the\nincident?","options":[["A","Root cause analysis"],["B","Detection"],["C","E-discovery"],["D","Lessons learned"]],"correct":"A"},{"num":409,"text":"Which of the following is the greatest advantage that network segmentation provides?","options":[["A","End-to-end encryption"],["B","Decreased resource utilization"],["C","Enhanced endpoint protection"],["D","Configuration enforcement"],["E","Security zones"]],"correct":"E"},{"num":410,"text":"Which of the following is a directive managerial control?","options":[["A","Acceptable use policy"],["B","Log-in warning banner"],["C","Master service agreement"],["D","No trespassing sign"]],"correct":"A"},{"num":411,"text":"Which of the following is the best way to prevent data from being leaked from a secure network that does\nnot need to communicate externally?","options":[["A","Air gap"],["B","Containerization"],["C","Virtualization"],["D","Decentralization"]],"correct":"A"},{"num":412,"text":"Which of the following activities identifies but does not exploit vulnerabilities?","options":[["A","Penetration test"],["B","Static analysis"],["C","Dynamic analysis"],["D","Bug bounty"]],"correct":"B"},{"num":413,"text":"A penetration tester was able to gain unauthorized access to a hypervisor platform. Which of the following\nvulnerabilities was most likely exploited?","options":[["A","Cross-site scripting"],["B","SQL injection"],["C","Race condition"],["D","VM escape"]],"correct":"D"},{"num":414,"text":"An attacker defaces a company's website and refuses to relinquish control until the company removes\nspecific harmful chemicals from its products. Which of the following best describes this type of threat actor?","options":[["A","Unskilled attacker"],["B","Hacktivist"],["C","Organized crime"],["D","Espionage"]],"correct":"B"},{"num":415,"text":"A company uses a cloud-based server for file storage and wants to ensure the security of its data in transit.\nWhich of the following should the company use to secure this type of communication? (Choose two.)","options":[["A","TLS certificates"],["B","WPA2 encryption"],["C","HTTPS"],["D","Virtual private network"],["E","Encryption key management"],["F","Digital signatures"]],"correct":"AD"},{"num":416,"text":"An organization found gaps in its software development environment and is implementing compensating\ncontrols to better protect its systems from external threats. Which of the following would be most effective?\n(Choose two.)","options":[["A","Platform hardening"],["B","Expanded logging"],["C","Network segmentation"],["D","Access control"],["E","Data encryption"],["F","Application allow list"]],"correct":"AF"},{"num":417,"text":"Which of the following is a qualitative approach to risk analysis?","options":[["A","Including the MTTR and MTBF as part of the risk assessment"],["B","Tracking and documenting network risks using a risk register"],["C","Assigning a level of high, medium, or low to the risk rating"],["D","Using ALE and ARO to help determine whether a risk should be mitigated"]],"correct":"C"},{"num":418,"text":"Which of the following provides resilience by hosting critical VMs within different IaaS providers while being\nmaintained by internal application owners?","options":[["A","Multicloud architectures"],["B","SaaS provider diversity"],["C","On-premises server load balancing"],["D","Corporate-owned, off-site locations"]],"correct":"A"},{"num":419,"text":"While a user reviews their email, a host gets infected by malware that came from an external hard drive\nplugged into the host. The malware steals all the user's credentials stored in the browser. Which of the\nfollowing training topics should the user review to prevent this situation from reoccurring?","options":[["A","Operational security"],["B","Removable media and cables"],["C","Password management"],["D","Social engineering"]],"correct":"B"},{"num":420,"text":"An organization keeps servers with confidential information in the same network as workstations. An\nattacker compromises a workstation and moves laterally to a server. Which of the following could have\nprevented the attacker from accessing the server?","options":[["A","Load balancers"],["B","Security zones"],["C","Virtual private networks"],["D","Proxy servers"]],"correct":"B"},{"num":421,"text":"An administrator needs to ensure all emails sent and received by a specific address are stored in a nonalterable format. Which of the following best describes this forensic concept?","options":[["A","E-discovery"],["B","Acquisition"],["C","Legal hold"],["D","Chain of custody"]],"correct":"B"},{"num":422,"text":"A company recently purchased a new building that does not have an existing wireless or wired\ninfrastructure. A network engineer at the company needs to determine the placement of the access points\nin the new building. Which of the following accurately describes the task the network engineer will be\nperforming?","options":[["A","Heat map"],["B","Internal assessment"],["C","Corporate reconnaissance"],["D","Site survey"]],"correct":"D"},{"num":423,"text":"Which of the following should a systems administrator do after performing remediation activities?","options":[["A","Classify"],["B","Archive"],["C","Rescan"],["D","Isolate"]],"correct":"C"},{"num":424,"text":"An organization wants to increase an application's resiliency by configuring access to multiple servers in the\norganization's geographically dispersed environment. Which of the following best describes this\narchitecture?","options":[["A","Containerized"],["B","Multitenant"],["C","Load balanced"],["D","Virtualized"]],"correct":"C"},{"num":425,"text":"A user attempts to send an invoice to a customer. When the user follows up with the customer to see if the\ninvoice was received, the customer informs the user that it went to the spam folder. The management team\nhas asked the systems administrator to implement measures to reduce the likelihood of this happening\nagain by implementing server authentication. Which of the following should the systems administrator\nimplement?","options":[["A","SPF"],["B","DMARC"],["C","XDR"],["D","DNSSEC"]],"correct":"A"},{"num":426,"text":"A database engineer needs sample customer data for testing purposes. Which of the following can prevent\nunauthorized viewing or disclosure of PII?","options":[["A","Masking"],["B","RBAC"],["C","Tokenization"],["D","Filtering"]],"correct":"A"},{"num":427,"text":"A user sends an email that includes a digital signature for validation. Which of the following security\nconcepts would ensure a user cannot deny they sent the email?","options":[["A","Non-repudiation"],["B","Confidentiality"],["C","Integrity"],["D","Authentication"]],"correct":"A"},{"num":428,"text":"A company's leadership team wants to ensure employees only print business-related documents on\ncompany printers. Which of the following documents should the company add this directive to?","options":[["A","Information security policy"],["B","Data classification policy"],["C","Business continuity plan"],["D","Acceptable use policy"]],"correct":"D"},{"num":429,"text":"An employee receives from a vendor a marketing communication email that includes an attachment. When\nthe employee opens the attachment, the employee's screen displays odd text requesting payment in order\nto recover data. Within moments, a company-wide email is sent to employees requesting that employees\ndisconnect their computers from the internet and shut them down. Which of the following describes this\ntype of malware?","options":[["A","Trojan"],["B","Worm"],["C","Ransomware"],["D","Virus"]],"correct":"C"},{"num":430,"text":"Which of the following is a technical security control?","options":[["A","Security guard"],["B","Policy"],["C","Fence"],["D","Firewall"]],"correct":"D"},{"num":431,"text":"An organization decides that most employees will work remotely. The existing VPN solution does not have\nadequate bandwidth, and the content filtering proxy is on premises. Which of the following strategies will\nenable the business to securely achieve its objective while also being prepared to quickly scale for growth?","options":[["A","Integrate with an SASE platform, and deploy the agent to all laptops."],["B","Purchase a larger internet circuit, and create a NAT policy for the proxy."],["C","Purchase a SOAR solution to decrease response times for remote workers."],["D","Install a secondary VPN and proxy at the disaster recovery site, and automate failover."]],"correct":"A"},{"num":432,"text":"Which of the following is the most likely reason a security analyst would review SIEM logs?","options":[["A","To check for recent password reset attempts"],["B","To monitor for potential DDoS attacks"],["C","To assess the scope of a privacy breach"],["D","To see correlations across multiple hosts"]],"correct":"D"},{"num":433,"text":"Which of the following would help reduce alert fatigue?","options":[["A","Penetration testing"],["B","Compensating controls"],["C","Rule tuning"],["D","Log aggregation"]],"correct":"C"},{"num":434,"text":"Which of the following options most efficiently maintains a system state in the event of a system failure?","options":[["A","Hybrid cloud"],["B","Cold site"],["C","Full backup"],["D","Load balancing"]],"correct":"D"},{"num":435,"text":"During a SQL update of a database, a temporary field used as part of the update sequence was modified by\nan attacker before the update completed in order to allow access to the system. Which of the following best\ndescribes this type of vulnerability?","options":[["A","Race condition"],["B","Memory injection"],["C","Malicious update"],["D","Side loading"]],"correct":"A"},{"num":436,"text":"A company's accounts payable clerk receives a message from a vendor asking to change their bank\naccount before paying an invoice. The clerk makes the change and sends the payment to the new account.\nDays later, the clerk receives another message from the same vendor with a request for a missing payment\nto the original bank account. Which of the following has most likely occurred?","options":[["A","Phishing campaign"],["B","Data exfiltration"],["C","Pretext calling"],["D","Business email compromise"]],"correct":"D"},{"num":437,"text":"A vendor salesperson is a personal friend of a company's Chief Financial Officer (CFO). The company\nrecently made a large purchase from the vendor, which was directly approved by the CFO. Which of the\nfollowing best describes this situation?","options":[["A","Rules of engagement"],["B","Conflict of interest"],["C","Due diligence"],["D","Contractual impact"],["E","Reputational damage"]],"correct":"B"},{"num":438,"text":"The board of a company needs to tell the leadership team which activities are too risky to undertake during\nbusiness operations. Which of the following risk management strategies does the board need to explain to\nthe leadership team?","options":[["A","The company's risk assessment"],["B","The company's risk acceptance"],["C","The company's risk register"],["D","The company's risk tolerance"]],"correct":"D"},{"num":439,"text":"A systems administrator wants to use a technical solution to explicitly define file permissions for the entire\nteam. Which of the following should the administrator implement?","options":[["A","ACL"],["B","Monitoring"],["C","Isolation"],["D","HIPS"]],"correct":"A"},{"num":440,"text":"A company is concerned with supply chain compromise of new servers and wants to limit this risk. Which of\nthe following should the company review first?","options":[["A","Sanitization procedure"],["B","Acquisition process"],["C","Change management"],["D","Asset tracking"]],"correct":"B"},{"num":441,"text":"A security analyst receives an alert from a front-end web server connected to a database back end. The\nalert contains the following logs:\n\nWhich of the following attacks is occurring?","options":[["A","Buffer overflow"],["B","Brute-force"],["C","Injection"],["D","Replay"]],"correct":"C"},{"num":442,"text":"Which of the following control types involves restricting IP connectivity to a router's web management\ninterface to protect it from being exploited by a vulnerability?","options":[["A","Corrective"],["B","Physical"],["C","Preventive"],["D","Managerial"]],"correct":"C"},{"num":443,"text":"Which of the following data types relates to data sovereignty?","options":[["A","Data classified as public in other countries"],["B","Personally identifiable data while traveling"],["C","Health data shared between doctors in other nations"],["D","Data at rest outside of a country's borders"]],"correct":"D"},{"num":444,"text":"A software developer wishes to implement an application security technique that will provide assurance of\nthe application\u2019s integrity. Which of the following techniques will achieve this?","options":[["A","Secure cookies"],["B","Input validation"],["C","Static analysis"],["D","Code signing"]],"correct":"D"},{"num":445,"text":"A penetration test reveals that users can easily access internal VLANs from the company's guest Wi-Fi.\nWhich of the following security principles would remediate this vulnerability by improving network\nauthentication mechanisms?","options":[["A","VLAN ACLs"],["B","Captive portal"],["C","DNSSEC"],["D","802.1X"]],"correct":"D"},{"num":446,"text":"A company recently set up a system for employees to access their files remotely. However, the IT team has\nnoticed that some employees are using personal devices to access the system. Which of the following\nsecurity techniques could help mitigate the risk of unauthorized connections by personal devices?","options":[["A","Multifactor Authentication"],["B","Conditional Access Policies"],["C","Cloud Access Security Broker"],["D","Data Loss Prevention"]],"correct":"B"},{"num":447,"text":"Which of the following security controls is a company implementing by deploying HIPS? (Choose two.)","options":[["A","Directive"],["B","Preventive"],["C","Physical"],["D","Corrective"],["E","Compensating"],["F","Detective"]],"correct":"BF"},{"num":448,"text":"Which of the following is the best physical security measure that prevents unauthorized vehicles from\nentering a data center while still allowing foot traffic?","options":[["A","Access control vestibules"],["B","Fencing"],["C","Video surveillance"],["D","Retractable bollards"]],"correct":"D"},{"num":449,"text":"Which of the following are the best methods for hardening end user devices? (Choose two.)","options":[["A","Full disk encryption"],["B","Group-level permissions"],["C","Account lockout"],["D","Endpoint protection"],["E","Proxy server"],["F","Segmentation"]],"correct":"AD"},{"num":450,"text":"Which of the following policies outlines what employees can and cannot do on company-issued devices?","options":[["A","Acceptable use"],["B","Data classification"],["C","Change management"],["D","Business continuity"]],"correct":"A"},{"num":451,"text":"A developer receives this message when testing a new external website:\nThis site cannot be reached.\nWhich of the following logs would most likely help identify the root cause?","options":[["A","Firewall"],["B","IDS"],["C","Application"],["D","System"]],"correct":"A"},{"num":452,"text":"Which of the following methods to secure data is most often used to protect data in transit?","options":[["A","Encryption"],["B","Obfuscation"],["C","Permission restrictions"],["D","Hashing"]],"correct":"A"},{"num":453,"text":"Which of the following does a user often agree to when logging in to a domain?","options":[["A","AUP"],["B","MAC"],["C","EULA"],["D","EAP"]],"correct":"A"},{"num":454,"text":"A Chief Information Security Officer wants to enhance security capabilities to block PH from being emailed\nor downloaded to unapproved external media. Which of the following solutions will accomplish this goal?","options":[["A","Deploying DLP software on servers and endpoints"],["B","Configuring servers and endpoints to use a centralized web proxy"],["C","Implementing secure protocols on servers and endpoints"],["D","Installing EDR software on servers and endpoints"]],"correct":"A"},{"num":455,"text":"After a breach at a data processing center, an administrator receives a notification that administrative\npasswords were leaked online. Which of the following should be used to prevent this incident from\noccurring in the future?","options":[["A","Password management"],["B","Password complexity"],["C","Password policy"],["D","Password vault"]],"correct":"D"},{"num":456,"text":"A systems administrator has overwritten all of the supervisor's permissions in order to perform malicious\nactivities. Which of the following does this describe?","options":[["A","Shadow IT"],["B","Unskilled attacker"],["C","Insider threat"],["D","Hacktivist"]],"correct":"C"},{"num":457,"text":"Which of the following would best prepare a security team for a specific incident response scenario?","options":[["A","Situational awareness"],["B","Risk assessment"],["C","Root cause analysis"],["D","Tabletop exercise"]],"correct":"D"},{"num":458,"text":"Which of the following would best ensure a controlled version release of a new software application?","options":[["A","Business continuity planning"],["B","Quantified risk analysis"],["C","Static code analysis"],["D","Change management procedures"]],"correct":"D"},{"num":459,"text":"Several employees download a productivity program that is useful but also leaks contact information and\ncorporate organizational structure details. Which of the following is the best way to prevent this issue?","options":[["A","Application allow list"],["B","Workstation hardening"],["C","Refusal of unsigned code"],["D","IP blocklist"],["E","Standard user accounts"]],"correct":"A"},{"num":460,"text":"The Chief Executive Officer has requested that a vendor conduct a penetration test without engaging the\ninternal IT team to validate the company's investment in security tools, awareness training, and SOC\npersonnel. Which of the following penetration testing methods is most likely being used?","options":[["A","Unknown"],["B","Known"],["C","Integrated"],["D","Partially known"]],"correct":"A"},{"num":461,"text":"A user receives an aggressive text from an unknown sender who is demanding money. Which of the\nfollowing attacks is this an example of?","options":[["A","Impersonation"],["B","Typosquatting"],["C","Smishing"],["D","Scareware"]],"correct":"C"},{"num":462,"text":"Employees receive a text message containing a link to a web page that prompts the user to enter their ID\nand a work phone number. The text message appears to come from the Chief Executive Officer, but it is\nlater discovered that the message is not legitimate. Which of the following does this best represent?\n(Choose two.)","options":[["A","Misinformation"],["B","Smishing"],["C","Impersonation"],["D","Typosquatting"],["E","Pretexting"],["F","Phishing"]],"correct":"BC"},{"num":463,"text":"A security engineer needs to patch an OS vulnerability that impacts all corporate laptops. Which of the\nfollowing is necessary to ensure all corporate laptops are patched?","options":[["A","Ownership"],["B","Inventory"],["C","Classification"],["D","Enumeration"]],"correct":"B"},{"num":464,"text":"Which of the following threat vectors would a user be vulnerable to when using a smartphone to scan a twodimensional matrix barcode?","options":[["A","Quishing"],["B","Smishing"],["C","Vishing"],["D","Phishing"]],"correct":"A"},{"num":465,"text":"Which of the following is most likely a security concern when installing and using low-cost IoT devices in\ninfrastructure environments?","options":[["A","Counterfeit products"],["B","Device responsiveness"],["C","Ease of deployment"],["D","Data remanence"]],"correct":"A"},{"num":466,"text":"Which of the following are activities that should be completed during the containment and eradication\nphases of the incident response process? (Choose two.)","options":[["A","Notifying stakeholders"],["B","Restoring the system"],["C","Identifying the threat"],["D","Removing the malicious threat"],["E","Developing a recovery plan"],["F","Analyzing the incident"]],"correct":"CD"},{"num":467,"text":"All clients who connect to the switchports are required to complete a posture analysis before accessing the\ninternet. Which of the following should the IT team configure to help secure the enterprise infrastructure?","options":[["A","VPN"],["B","WAF"],["C","IPS"],["D","NAC"]],"correct":"D"},{"num":468,"text":"An attorney prints confidential documents to a copier in an office space near multiple workstations and a\nreception desk. When the attorney goes to the copier to retrieve the documents, the documents are\nmissing. Which of the following would best prevent this from reoccurring?","options":[["A","Place the copier in the legal department."],["B","Configure DLP on the attorney's workstation."],["C","Set up LDAP authentication on the printer."],["D","Conduct a physical penetration test."]],"correct":"C"},{"num":469,"text":"Which of the following activities should a systems administrator perform to quarantine a potentially infected\nsystem?","options":[["A","Move the device into an air-gapped environment."],["B","Disable remote log-in through Group Policy."],["C","Convert the device into a sandbox."],["D","Remote wipe the device using the MDM platform."]],"correct":"A"},{"num":470,"text":"Which of the following can be deployed in data centers as a protection against an undervoltage event?","options":[["A","Resource management"],["B","Load balancer"],["C","Surge protector"],["D","Uninterruptable power supply"]],"correct":"D"},{"num":471,"text":"According to various privacy rules and regulations, users have the power to request that all data pertaining\nto them is deleted. This is known as:","options":[["A","right to be forgotten."],["B","attestation and acknowledgement."],["C","data retention."],["D","information deletion."]],"correct":"A"},{"num":472,"text":"An analyst identifies that multiple users have the same passwords, but the hashes appear to be completely\ndifferent. Which of the following most likely explains this issue?","options":[["A","Data masking"],["B","Salting"],["C","Key escrow"],["D","Tokenization"]],"correct":"B"},{"num":473,"text":"An employee receives a work phone. Instead of starting up with the normal operating system, the phone\nloads to a gaming platform using administrative credentials. Which of the following issues occurred?","options":[["A","Misconfiguration"],["B","Side loading"],["C","Malicious update"],["D","Jailbreaking"]],"correct":"D"},{"num":474,"text":"A university uses two different cloud solutions for storing student data. Which of the following does this\nrepresent?","options":[["A","Load balancer"],["B","Parallel processing"],["C","Platform diversity"],["D","Clustering"]],"correct":"C"},{"num":475,"text":"An employee clicked a malicious link in an email and downloaded malware onto the company's computer\nnetwork. The malicious program exfiltrated thousands of customer records. Which of the following should\nthe company implement to best prevent this in the future?","options":[["A","User awareness training"],["B","Network monitoring"],["C","Endpoint protection"],["D","Data loss prevention"]],"correct":"C"},{"num":476,"text":"A forensic engineer determines that the root cause of a compromise is a SQL injection attack. Which of the\nfollowing should the engineer review to identify the command used by the threat actor?","options":[["A","Metadata"],["B","Application log"],["C","System log"],["D","Netflow log"]],"correct":"B"},{"num":477,"text":"In which of the following will unencrypted PLC management traffic most likely be found?","options":[["A","SDN"],["B","IoT"],["C","VPN"],["D","SCADA"]],"correct":"D"},{"num":478,"text":"An administrator must implement a solution that provides security and network connectivity between two\ncompanies. Which of the following infrastructure solutions is the best for this purpose?","options":[["A","UTM"],["B","VPN"],["C","NAC"],["D","NGFW"]],"correct":"B"},{"num":479,"text":"A software engineering manager wants to scan the code for security vulnerabilities before it is pushed into\nproduction. Which of the following types of analysis should the manager select?","options":[["A","Static"],["B","Threat"],["C","Packet"],["D","Dynamic"],["E","Package"]],"correct":"A"},{"num":480,"text":"A security team purchases a tool for cloud security posture management. The team is quickly overwhelmed\nby the number of misconfigurations the tool detects. Which of the following should the security team\nconfigure to establish secure baselines for cloud resource usage?","options":[["A","CASB"],["B","IAM"],["C","Guardrails"],["D","XDR"]],"correct":"C"},{"num":481,"text":"Which of the following is a social engineering attack in which a bad actor impersonates a web URL?","options":[["A","Pretexting"],["B","Misinformation"],["C","Typosquatting"],["D","Watering-hole"]],"correct":"C"},{"num":482,"text":"A company is in the process of cutting jobs to manage costs. The Chief Information Security Officer is\nconcerned about the increased risk of an insider threat. Which of the following would most likely help the\nsecurity awareness team address this potential threat?","options":[["A","Immediately disable the accounts of staff who are likely to be terminated."],["B","Train supervisors to identify and manage disgruntled employees."],["C","Configure DLP to monitor staff who will be terminated."],["D","Raise awareness for business leaders on social engineering techniques."]],"correct":"B"},{"num":483,"text":"A security analyst is prioritizing vulnerability scan results using a risk-based approach. Which of the\nfollowing is the most efficient resource for the analyst to use?","options":[["A","Business impact analysis"],["B","Common Vulnerability Scoring System"],["C","Risk register"],["D","Exposure factor"]],"correct":"B"},{"num":484,"text":"A penetration tester visits a client's website and downloads the site's content. Which of the following actions\nis the penetration tester performing?","options":[["A","Unknown environment testing"],["B","Vulnerability scan"],["C","Due diligence"],["D","Passive reconnaissance"]],"correct":"D"},{"num":485,"text":"Which of the following actions must an organization take to comply with a person's request for the right to\nbe forgotten?","options":[["A","Purge all personally identifiable attributes."],["B","Encrypt ail of the person's data."],["C","Remove all of the person's data."],["D","Obfuscate all of the person's data."]],"correct":"C"},{"num":486,"text":"An administrator must authenticate users to systems using credentials already authenticated by a business\npartner's LDAP system. Which of the following should the administrator deploy to enable this functionality?","options":[["A","Media access control"],["B","Interoperability"],["C","OAUTH"],["D","Federation"]],"correct":"D"},{"num":487,"text":"The help desk receives multiple calls indicating machines with an outdated OS version are running slowly.\nSeveral users report seeing virus detection alerts. Which of the following mitigation techniques should be\nreviewed first?","options":[["A","Patching"],["B","Segmentation"],["C","Monitoring"],["D","Isolation"]],"correct":"A"},{"num":488,"text":"Which of the following actions should be performed on end-of-life equipment before it is discarded?","options":[["A","Isolation"],["B","Patching"],["C","Decommissioning"],["D","Monitoring"]],"correct":"C"},{"num":489,"text":"Which of the following actions would reduce the number of false positives for an analyst to manually\nreview?","options":[["A","Create playbooks as part of a SOAR platform."],["B","Redefine the patch management process."],["C","Replace an EDR tool with an XDR solution."],["D","Disable AV heuristics scanning."]],"correct":"A"},{"num":490,"text":"A government agency requires publicly traded organizations to report cyber breaches within a designated\ntime period. By law, these reports are made public. Which of the following could cause loss of existing and\nfuture business for an organization after reports are published?","options":[["A","Fines and penalties"],["B","Reputational damage"],["C","Board oversight"],["D","Conflicts of interest"]],"correct":"B"},{"num":491,"text":"Which of the following would a service provider supply as an assurance for a disposal service as part of a\ndisposal process?","options":[["A","Insurance"],["B","Certification"],["C","Classification"],["D","Retention"]],"correct":"B"},{"num":492,"text":"The security department is remediating vulnerabilities that were found during an audit of newly deployed\nsystems. Which of the following must be done to ensure compliance?","options":[["A","Confirm false positives."],["B","Review the attack surface."],["C","Conduct a rescan."],["D","Report the remediations."]],"correct":"C"},{"num":493,"text":"A company with a high-availability website is looking to harden its controls at any cost. The company wants\nto ensure that the site is secure by finding any possible issues. Which of the following would most likely\nachieve this goal?","options":[["A","Permission restrictions"],["B","Bug bounty program"],["C","Vulnerability scan"],["D","Reconnaissance"]],"correct":"B"},{"num":494,"text":"A human resources (HR) employee working from home leaves their company laptop open on the kitchen\ntable. A family member walking through the kitchen reads an email from the Chief Financial Officer\naddressed to the HR department. The email contains information referencing company layoffs. The family\nmember posts the content of the email to social media. Which of the following policies will the HR employee\nmost likely need to review after this incident?","options":[["A","Hybrid work environment"],["B","Operation security"],["C","Data loss prevention"],["D","Social engineering"]],"correct":"B"},{"num":495,"text":"A government worker secretly copies classified files that contain defense tactics information to an external\ndrive. The government worker then gives the external drive to a corrupt organization. Which of the following\nbest describes the motivation of the worker?","options":[["A","Espionage"],["B","Data exfiltration"],["C","Financial gain"],["D","Blackmail"]],"correct":"A"},{"num":496,"text":"A Chief Security Officer signs off on a request to allow inbound SMB and RDP from the internet to a single\nVLAN. Which of the following is the most likely explanation for this activity?","options":[["A","The company built a new file-sharing site."],["B","The IT team requested a new jump host."],["C","The security team is integrating with an SASE platform."],["D","The security team created a honeynet."]],"correct":"D"},{"num":497,"text":"A systems administrator discovers a guest user gained access to classified reports. Upon further\ninvestigation, the logs indicate that the user was added to the administrator group. Which of the following\nbest describes this attack?","options":[["A","Credential replay"],["B","Privilege escalation"],["C","Directory traversal"],["D","Brute-force"]],"correct":"B"},{"num":498,"text":"Which of the following sites offers immediate service restoration following a disaster?","options":[["A","Cloud-based"],["B","Hot"],["C","Warm"],["D","Cold"]],"correct":"B"},{"num":499,"text":"Which of the following is an example of a certificate that is generated by an internal source?","options":[["A","Digital signature"],["B","Asymmetric key"],["C","Self-signed"],["D","Symmetric key"]],"correct":"C"},{"num":500,"text":"Which of the following is a benefit of an RTO when conducting a business impact analysis?","options":[["A","It determines the likelihood of an incident and its cost."],["B","It determines the roles and responsibilities for incident responders."],["C","It determines the state that systems should be restored to following an incident."],["D","It determines how long an organization can tolerate downtime after an incident."]],"correct":"D"},{"num":501,"text":"A recent review of logs indicates many attempts to join an internal wireless network from external devices.\nThe connections appear to be originating from surrounding buildings. Which of the following would best\nhelp minimize the visibility of the wireless network?","options":[["A","Mobile device management"],["B","Pre-shared keys"],["C","Heat maps"],["D","Site survey"]],"correct":"D"},{"num":502,"text":"Which of the following data protection strategies can be used to confirm file integrity?","options":[["A","Masking"],["B","Encryption"],["C","Hashing"],["D","Obfuscation"]],"correct":"C"},{"num":503,"text":"An organization discovers that its cold site does not have enough storage and computers available. Which\nof the following was most likely the cause of this failure?","options":[["A","Capacity planning"],["B","Load balancing"],["C","Backups"],["D","Platform diversity"]],"correct":"A"},{"num":504,"text":"The security team notices that the Always On VPN solution sometimes fails to connect. This leaves remote\nusers unprotected because they cannot connect to the on-premises web proxy. Which of the following\nchanges will best provide web protection in this scenario?","options":[["A","Implement network access control."],["B","Configure the local gateway to point to the VPN."],["C","Create a public NAT to the on-premises proxy."],["D","Install a host-based content filtering solution."]],"correct":"D"},{"num":505,"text":"A security analyst wants to automate a task that shares data between programs. Which of the following is\nthe best option for the analyst to use?","options":[["A","SOAR"],["B","API"],["C","SFTP"],["D","RDP"]],"correct":"B"},{"num":506,"text":"An auditor notices that, before logging into the firewall, an employee opens a document in a shared folder\nthat contains administrative credentials. Which of the following should the auditor recommend\nimplementing?","options":[["A","Situational awareness"],["B","Operational security"],["C","Password management"],["D","Acceptable use policy"]],"correct":"C"},{"num":507,"text":"Which of the following attacks uses a website to collectively target a group of developers within an\norganization?","options":[["A","Typosquatting"],["B","Watering hole"],["C","Denial of service"],["D","Credential replay"]],"correct":"B"},{"num":508,"text":"Which of the following is the best reason to complete an audit in a banking environment?","options":[["A","Regulatory requirement"],["B","Organizational change"],["C","Self-assessment requirement"],["D","Service-level requirement"]],"correct":"A"},{"num":509,"text":"Which of the following is the most likely benefit of conducting an internal audit?","options":[["A","Findings are reported to shareholders"],["B","Reports are not formal and can be reassigned"],["C","Control gaps are identified for remediation"],["D","The need for external audits is eliminated"]],"correct":"C"},{"num":510,"text":"A security analyst identifies an employee who added an unauthorized wireless router to an office branch.\nAfter an investigation, the router is removed, and the employee is given mandatory retraining. Which of the\nfollowing best describes this incident?","options":[["A","Unskilled attacker"],["B","Hacktivist"],["C","Nation-state"],["D","Shadow IT"]],"correct":"D"},{"num":511,"text":"Which of the following is the best safeguard to protect against an extended power failure?","options":[["A","Off-site backups"],["B","Batteries"],["C","Uninterruptible power supplies"],["D","Generators"]],"correct":"D"},{"num":512,"text":"Users see a certificate warning on their browsers when connecting to the server over HTTPS. Which of the\nfollowing is the most likely cause?","options":[["A","The server is using a wildcard certificate"],["B","The server is using a root certificate"],["C","The server is using no certificate at all"],["D","The server is using a self-signed certificate"]],"correct":"D"},{"num":513,"text":"Prior to implementing a design change, the change must go through multiple steps to ensure that it does\nnot cause any security issues. Which of the following is most likely to be one of those steps?","options":[["A","Management review"],["B","Load testing"],["C","Maintenance notifications"],["D","Procedure updates"]],"correct":"A"},{"num":514,"text":"Which of the following is a benefit of launching a bug bounty program? (Choose two.)","options":[["A","Improved reputation for the organization"],["B","Reduction in the number of zero-day vulnerabilities"],["C","Increased security awareness for the workforce"],["D","Reduced cost of managing the program"],["E","Quicker discovery of vulnerabilities"],["F","Improved patch management process"]],"correct":"AE"},{"num":515,"text":"Which of the following best explains a concern with OS-based vulnerabilities?","options":[["A","An exploit would give an attacker access to system functions that span multiple applications"],["B","The OS vendor's patch cycle Is not frequent enough to mitigate the large number of threats"],["C","Most users trust the core operating system features and may not notice if the system has been"],["D","Exploitation of an operating system vulnerability is typically easier than any other vulnerability"]],"correct":"A"},{"num":516,"text":"During a penetration test in a hypervisor, the security engineer is able to use a script to inject a malicious\npayload and access the host filesystem. Which of the following best describes this vulnerability?","options":[["A","VM escape"],["B","Cross-site scripting"],["C","Malicious update"],["D","SQL injection"]],"correct":"A"},{"num":517,"text":"Which of the following security controls are a company implementing by deploying HIPS? (Choose two.)","options":[["A","Directive"],["B","Preventive"],["C","Physical"],["D","Corrective"],["E","Compensating"],["F","Detective"]],"correct":"BF"},{"num":518,"text":"Which of the following describes effective change management procedures?","options":[["A","Approving the change after a successful deployment"],["B","Having a backout plan when a patch fails"],["C","Using a spreadsheet for tracking changes"],["D","Using an automatic change control bypass for security updates"]],"correct":"B"},{"num":519,"text":"A company is experiencing a high number of users who are clicking on email-based attacks even though\nthose users have completed annual training. The company's Chief Security Officer wants to identify and\nreduce which users are phished the most often. Which of the following will best achieve this result?","options":[["A","Begin a semiannual in-person training course with mandatory attendance. The users would perform"],["B","Deploy a product that would occasionally send users emails to simulate an attack. The product would"],["C","Hire a security consultant to give a personalized seminar at the company. The consultant would share"],["D","Require an MFA when signing in to the email client. Users would need to authenticate once a week at a"]],"correct":"B"},{"num":520,"text":"Which of the following mitigation techniques would a security analyst most likely use to avoid bloatware on\ndevices?","options":[["A","Disabled ports/protocols"],["B","Application allow list"],["C","Default password changes"],["D","Access control permissions"]],"correct":"B"},{"num":521,"text":"A company decides to purchase an insurance policy. Which of the following risk management strategies is\nthis company implementing?","options":[["A","Mitigate"],["B","Accept"],["C","Avoid"],["D","Transfer"]],"correct":"D"},{"num":522,"text":"Which of the following principles requires that a company must keep files or records for a prescribed period\nof time before it disposes of those files or records?","options":[["A","Data verification"],["B","Data backups"],["C","Data archiving"],["D","Data retention"]],"correct":"D"},{"num":523,"text":"A security analyst is monitoring logs from the organization's SIEM and identifies logs related to one of their\nsalespeople:\n\nWhich of the following is being displayed in the logs?","options":[["A","Impossible travel"],["B","SMTP replay"],["C","Directory traversal"],["D","Cross-site request forgery"]],"correct":"A"},{"num":524,"text":"A company wants to update its disaster recovery plan to include a dedicated location for immediate\ncontinued operations if a catastrophic event occurs. Which of the following options is best to include in the\ndisaster recovery plan?","options":[["A","Hot site"],["B","Warm site"],["C","Geolocation"],["D","Cold site"]],"correct":"A"},{"num":525,"text":"Which of the following attacks exploits a potential vulnerability as a result of direct access to a system using\nweak cryptographic algorithms?","options":[["A","Password cracking"],["B","On-path"],["C","Digital signing"],["D","Side-channel"]],"correct":"A"},{"num":527,"text":"Which of the following describes the reason for using an MDM solution to prevent jailbreaking?","options":[["A","To secure end-of-life devices from incompatible firmware updates"],["B","To avoid hypervisor attacks through VM escape"],["C","To eliminate buffer overflows at the application layer"],["D","To prevent users from changing the OS of mobile devices"]],"correct":"D"},{"num":528,"text":"Which of the following is the best mitigation for a zero-day vulnerability found in mission-critical production\nservers that must be highly available?","options":[["A","Virtualizing and migrating to a containerized instance"],["B","Removing and sandboxing to an isolated network"],["C","Monitoring and implementing compensating controls"],["D","Patching and redeploying to production as quickly as possible"]],"correct":"C"},{"num":529,"text":"An administrator has configured a quarantine subnet for all guest devices that connect to the network.\nWhich of the following would be best for the security team to configure on the MDM before allowing access\nto corporate resources?","options":[["A","Device fingerprinting"],["B","Compliance attestation"],["C","NAC"],["D","802.1X"]],"correct":"B"},{"num":530,"text":"A security team receives reports about high latency and complete network unavailability throughout most of\nthe office building. Flow logs from the campus switches show high traffic on TCP 445. Which of the\nfollowing is most likely the root cause of this incident?","options":[["A","Buffer overflow"],["B","NTP amplification attack"],["C","Worm"],["D","Kerberoasting attack"]],"correct":"C"},{"num":531,"text":"A company executive connects to various networks, such as hotel guest Wi-Fi. while traveling. A security\nanalyst needs to provide a solution that will allow the executive to securely access the corporate internal\nresources. Which of the following would best meet this requirement?","options":[["A","EAP"],["B","Jump server"],["C","Perimeter network"],["D","VPN"]],"correct":"D"},{"num":532,"text":"Which of the following architecture models ensures that critical systems are physically isolated on the\nnetwork to prevent access from users with remote access privileges?","options":[["A","Segmentation"],["B","Virtualized"],["C","Air-gapped"],["D","Serverless"]],"correct":"C"},{"num":533,"text":"A security team installs an IPS on an organization's network and needs to configure the system to detect\nand prevent specific network attacks. Which of the following settings should the team configure first within\nthe IPS?","options":[["A","Allow list policies"],["B","Packet inspection"],["C","Logging and reporting"],["D","Firewall rules"]],"correct":"B"},{"num":534,"text":"A security analyst must prevent remote users from accessing malicious URLs. The sites need to be\nchecked inline for reputation, content, or categorization. Which of the following technologies will help secure\nthe enterprise?","options":[["A","VPN"],["B","SASE"],["C","NGFW"],["D","SD-WAN"]],"correct":"B"},{"num":535,"text":"A systems administrator needs to provide traveling employees with a security measure that will protect\ncompany devices regardless of where they are working. Which of the following should the administrator\nimplement?","options":[["A","Isolation"],["B","Segmentation"],["C","ACL"],["D","HIPS"]],"correct":"D"},{"num":536,"text":"Which of the following is used to monitor suspicious traffic in real time between multiple systems within an\norganization?","options":[["A","NetFlow"],["B","Infrared sensors"],["C","Development network"],["D","Honeynet"]],"correct":"A"},{"num":537,"text":"A remote employee navigates to a shopping website on their company-owned computer. The employee\nclicks a link that contains a malicious file. Which of the following would prevent this file from downloading?","options":[["A","DLP"],["B","FIM"],["C","NAC"],["D","EDR"]],"correct":"D"},{"num":538,"text":"A security analyst is reviewing the security of a SaaS application that the company intends to purchase.\nWhich of the following documentations should the security analyst request from the SaaS application\nvendor?","options":[["A","Service-level agreement"],["B","Third-party audit"],["C","Statement of work"],["D","Data privacy agreement"]],"correct":"B"},{"num":539,"text":"A security administrator protects passwords by using hashing. Which of the following best describes what\nthe administrator is doing?","options":[["A","Adding extra characters at the end to increase password length"],["B","Generating a token to make the passwords temporal"],["C","Using mathematical algorithms to make passwords unique"],["D","Creating a rainbow table to protect passwords in a list"]],"correct":"C"},{"num":540,"text":"A customer changes the underlying file structure of a new mobile phone to install a keylogger with\nadministrator permissions. Which of the following does this best describe?","options":[["A","Resource reuse"],["B","Bloatware installation"],["C","Side loading"],["D","Jailbreaking"]],"correct":"D"},{"num":541,"text":"Which of the following digital forensics activities would a security team perform when responding to legal\nrequests in a pending investigation?","options":[["A","E-discovery"],["B","User provisioning"],["C","Firewall log export"],["D","Root cause analysis"]],"correct":"A"},{"num":542,"text":"A security analyst is reviewing the security or a SaaS application that the company intends to purchase.\nWhich of the following documentations should the security analyst request from the SaaS application\nvendor?","options":[["A","Service-level agreement"],["B","Third-party audit"],["C","Statement or work"],["D","Data privacy agreement"]],"correct":"B"},{"num":543,"text":"While a school district is performing state testing, a security analyst notices all internet services are\nunavailable. The analyst discovers that ARP poisoning is occurring on the network ana then terminates\naccess for the host. Which of the following is most likely responsive for this malicious activity?","options":[["A","Unskilled attacker"],["B","Shadow IT"],["C","Credential stuffing"],["D","DMARC failure"]],"correct":"A"},{"num":544,"text":"Which of the following hardening techniques must be applied on a container image before deploying it to a\nproduction environment? (Choose two.)","options":[["A","Remove default applications."],["B","Install a NIPS."],["C","Disable Telnet."],["D","Reconfigure the DNS."],["E","Add an SFTP server."],["F","Delete the public certificate."]],"correct":"AC"},{"num":545,"text":"Which of the following would best explain why a security analyst is running daily vulnerability scans on all\ncorporate endpoints?","options":[["A","To track the status of patching installations"],["B","To find shadow IT cloud deployments"],["C","To continuously monitor hardware inventory"],["D","To hunt for active attackers in the network"]],"correct":"A"},{"num":546,"text":"A security patch is applied to a server. Which of the following will validate this remediation?","options":[["A","Rescanning"],["B","Dynamic analysis"],["C","Reporting"],["D","Static analysis"]],"correct":"A"},{"num":547,"text":"The internal security team is investigating a suspicious attachment and wants to perform a behavior\nanalysis in an isolated environment. Which of the following will the security team most likely use?","options":[["A","Sandbox"],["B","Jump server"],["C","Work computer"],["D","Container"]],"correct":"A"},{"num":548,"text":"A company is required to use certified hardware when building networks. Which of the following best\naddresses the risks associated with procuring counterfeit hardware?","options":[["A","A thorough analysis of the supply chain"],["B","A legally enforceable corporate acquisition policy"],["C","A right to audit clause in vendor contracts and SOWs"],["D","An in-depth penetration test of all suppliers and vendors"]],"correct":"A"},{"num":549,"text":"An analyst discovers a suspicious item in the SQL server logs. Which of the following could be evidence of\nan attempted SQL injection?","options":[["A","cat /etc/shadow"],["B","dig 25.36.99.11"],["C","cd ../../../"],["D","UserId \u2013 10 OR 1-1"]],"correct":"D"},{"num":550,"text":"A company identified the potential for malicious insiders to harm the organization. Which of the following\nmeasures should the organization implement to reduce this risk?","options":[["A","Unified threat management"],["B","Web application firewall"],["C","User behavior analytics"],["D","Intrusion detection system"]],"correct":"C"},{"num":551,"text":"After completing onboarding at a company and reviewing the company\u2019s handbooks and AUP an employee\ndownloads an unapproved application on a company desktop. Which of the following is the best course of\naction tor the company to take?","options":[["A","Educate the employee's manager."],["B","Silently uninstall the software."],["C","Ensure the employee completes focused training."],["D","Terminate the employee."]],"correct":"C"},{"num":552,"text":"An organization has experienced a breach because a hacker utilized a standard users two-year-old\npassword that the hacker found on the dark web. Which of the following would have prevented this attack?","options":[["A","Privileged access management"],["B","Account lockout"],["C","Reuse policy"],["D","Complexity requirements"]],"correct":"C"},{"num":553,"text":"An organization has published a list of domains that end users are not authorized to visit on company\ndevices in order to mitigate data loss or installation or malicious code. A security analyst observes multiple\nsuccessful attempts to reach a new suspicious domain from an end user\u2019s workstation. Which of the\nfollowing options can best prevent future access to unauthorized domains?","options":[["A","Assign user awareness training."],["B","Modify the unauthorized content policy."],["C","Deploy an allow list."],["D","Update the proxy filters."]],"correct":"D"},{"num":554,"text":"Users report that certain processes from a batch job are not working correctly and various resources are\nunavailable. An application owner provides the source and destination address information, and the errors\nare replicated for troubleshooting purposes. Which of the following should the security team perform next to\nhelp isolate the ongoing issue?","options":[["A","Penetration testing"],["B","Packet capture"],["C","Vulnerability scan"],["D","Firewall rues analysis"]],"correct":"B"},{"num":555,"text":"A company is experiencing loss of availability due to excessive traffic to their front-end web servers. The\ncompany hires a digital forensics expert to investigate the incident. Which of the following logs should the\ndigital forensics expert review first to diagnose the details of this incident?","options":[["A","Router"],["B","Load balancer"],["C","Switch"],["D","Firewall"]],"correct":"B"},{"num":556,"text":"An employee decides to collect PII data from the company\u2019s system for personal use. The employee\ncompresses the data into a single encrypted file before sending the file to their personal email. The security\ndepartment becomes aware of the attempted misuse and blocks the attachment from leaving the corporate\nenvironment. Which of the following types of employee training would most likely reduce the occurrence of\nthis type of issue? (Choose two.)","options":[["A","Privacy legislation"],["B","Social engineering"],["C","Risk management"],["D","Company compliance"],["E","Phishing"],["F","Remote work"]],"correct":"AD"},{"num":557,"text":"Which of the following is the best way to remove personal data from a social media account that is no\nlonger being used?","options":[["A","Exercise the right to be forgotten."],["B","Uninstall the social media application."],["C","Perform a factory reset."],["D","Terminate the social media account."]],"correct":"A"},{"num":558,"text":"A Chief Information Security Officer (CISO) of an enterprise environment wants to ensure that users cannot\nnavigate to known malicious domains. The CISO also wants web traffic on the network inspected for\nmalicious activity. Which of the following actions should the CISO take?","options":[["A","Place the intrusion system into IPS mode to block incoming malicious domains, and ensure secure"],["B","Deploy EDR software on all company systems, and perform user behavior analytics to detect users"],["C","Ensure the company\u2019s name servers use DNS filtering, and configure systems to use a centralized TLS"],["D","Set up a NAC on all segments of the company network, and set the network firewall to block known"]],"correct":"C"},{"num":559,"text":"A user receives a malicious text message that routes to a fake bank login. Which of the following attack\ntypes does this scenario describe?","options":[["A","Impersonation"],["B","Phishing"],["C","Vishing"],["D","Smishing"]],"correct":"D"},{"num":560,"text":"A group of people is working together to run multiple ransomware attacks against targets that the group\nselected to yield the most financial gain. Which of the following best describes this type of activity?","options":[["A","Organized crime"],["B","Nation-state actor"],["C","Shadow IT"],["D","Hacktivism"]],"correct":"A"},{"num":561,"text":"A security officer observes that a software development team is not complying with its corporate security\npolicy on encrypting confidential data. Which of the following categories refers to this type of noncompliance?","options":[["A","External"],["B","Standard"],["C","Regulation"],["D","Internal"]],"correct":"D"},{"num":562,"text":"Which of the following data types best describes an AI tool developed by a company to automate the\nticketing system under a specific contract?","options":[["A","Classified"],["B","Regulated information"],["C","Open source"],["D","Intellectual property"]],"correct":"D"},{"num":563,"text":"Which of the following would best allow a company to prevent access to systems from the internet?","options":[["A","Containerization"],["B","Virtualization"],["C","SD-WAN"],["D","Air-gapped"]],"correct":"D"},{"num":564,"text":"While conducting a business continuity tabletop exercise, the security team becomes concerned by\npotential impacts if a generator were to develop a fault during an extended outage.\nWhich of the following is the team most likely to consider when conducting and planning infrastructure\nmaintenance activities?","options":[["A","RPO"],["B","ARO"],["C","MTBF"],["D","MTTR"]],"correct":"C"},{"num":565,"text":"A security analyst is working with the IT group to define appropriate procedures for the destruction of media\nand assets in the enterprise environment. Which of the following methods provides the strongest level of\nassurance that the data has been disposed of properly?","options":[["A","Degaussing"],["B","Multipass wipe"],["C","Hashing"],["D","Erasure"],["E","Shredding"]],"correct":"E"},{"num":566,"text":"Which of the following vulnerabilities results in an application running extremely slowly due to an abnormally\nlarge number of incoming packets?","options":[["A","Race conditions"],["B","Cross-site scripting"],["C","Buffer overflow"],["D","Side loading"]],"correct":"C"},{"num":567,"text":"A company experiences a breach. The investigation reveals that the threat actor used a zero-day\nvulnerability to gain access and move laterally. Which of the following would best improve the company\u2019s\nsecurity posture and minimize the time to detect this type of incident?","options":[["A","NAC"],["B","IDS"],["C","DLP"],["D","UBA"]],"correct":"D"},{"num":568,"text":"Which of the following prevents unauthorized modifications to internal processes, assets, and security\ncontrols?","options":[["A","Change management"],["B","Playbooks"],["C","Incident response"],["D","Acceptable use policy"]],"correct":"A"},{"num":569,"text":"A user sits in a coffee shop on a government-issued laptop. A stranger starts a conversation with the user\nand starts asking about where the user works, what division the user works in, and additional personal\ninformation. Which of the following best describes the stranger\u2019s behavior?","options":[["A","Insider threat"],["B","Phishing"],["C","Social engineering"],["D","Risky"]],"correct":"C"},{"num":570,"text":"A company\u2019s Chief Information Security Officer (CISO) wants to enhance the capabilities of the incident\nresponse team. The CISO directs the incident response team to deploy a tool that rapidly analyzes host and\nnetwork data from potentially compromised systems and forwards the data for further correlation and\nreporting. Which of the following tools should the incident response team deploy?","options":[["A","NAC"],["B","IPS"],["C","SIEM"],["D","EDR"]],"correct":"D"},{"num":571,"text":"Which of the following is a component of a risk register?","options":[["A","Key risk indicators"],["B","Continuous risk assessment"],["C","Risk appetite"],["D","Risk culture"]],"correct":"A"},{"num":572,"text":"Which of the following most securely protects data at rest?","options":[["A","TLS 1.2"],["B","AES-256"],["C","Masking"],["D","Salting"]],"correct":"B"},{"num":573,"text":"Which of the following is a vulnerability concern for end-of-life hardware?","options":[["A","Failure to follow hardware disposal procedures could result in unintended data release."],["B","The supply chain may not have replacement hardware."],["C","Newly released software may require computing resources not available on legacy hardware."],["D","The vendor may stop providing patches and updates."]],"correct":"D"},{"num":574,"text":"A company\u2019s security team is reviewing its business continuity plan and must determine the amount of time\nneeded for operations to resume after a disaster. Which of the following describes the time frame the\nsecurity team is trying to determine?","options":[["A","Recovery time objective"],["B","Recovery point objective"],["C","Mean time between failures"],["D","Mean time to repair"]],"correct":"A"},{"num":575,"text":"Which of the following is a risk for a company using end-of-life applications on its network?","options":[["A","Default credentials"],["B","Open service ports"],["C","Vulnerable software"],["D","Insecure networks"]],"correct":"C"},{"num":576,"text":"Which of the following makes IaC a preferred security architecture over traditional infrastructure models?","options":[["A","Common attacks are less likely to be effective."],["B","Configuration can be better managed and replicated."],["C","Outsourcing to a third party with more expertise in network defense is possible."],["D","Optimization can occur across a number of computing instances"]],"correct":"B"},{"num":577,"text":"Which of the following is an advantage of a microservice-based architecture over traditional software\narchitectures?","options":[["A","Updates can be done one or more times per day if security issues arise."],["B","Managing communication between microservices is more streamlined."],["C","The internal structure of the code is hidden from users, making exploits more difficult to write."],["D","The services are written by a single team and can be debugged more quickly."]],"correct":"A"},{"num":578,"text":"An organization purchases software from an overseas company. The organization\u2019s IDS solution detects\nthat advertising data from the software is unexpectedly reporting back to the overseas company. Which of\nthe following threat vectors does this best describe?","options":[["A","Espionage"],["B","Supply chain"],["C","Nation-state"],["D","Insider threat"]],"correct":"B"},{"num":579,"text":"Which of the following can be best used to discover a company\u2019s publicly available breach information?","options":[["A","OSINT"],["B","SIEM"],["C","CVE"],["D","CVSS"]],"correct":"A"},{"num":580,"text":"An accounting clerk sent money to an attacker\u2019s bank account after receiving fraudulent instructions over\nthe phone to use a new account. Which of the following would most likely prevent this activity in the future?","options":[["A","Standardizing security incident reporting"],["B","Executing regular phishing campaigns"],["C","Implementing insider threat detection measures"],["D","Updating processes for sending wire transfers"]],"correct":"D"},{"num":581,"text":"Which of the following agreements defines response time, escalation points, and performance metrics?","options":[["A","BPA"],["B","MOA"],["C","NDA"],["D","SLA"]],"correct":"D"},{"num":582,"text":"A private equity firm has been the target of protests. The firm discovers its public website has been\ndefaced. Which of the following is most likely the threat actor?","options":[["A","Nation-state"],["B","Unskilled attacker"],["C","Organized crime"],["D","Hacktivist"]],"correct":"D"},{"num":583,"text":"Which of the following is the most closely associated with confidentiality?","options":[["A","NDA"],["B","SOW"],["C","MOU"],["D","BPA"]],"correct":"A"},{"num":584,"text":"During an assessment, an organization provides a penetration tester with a website URL and login\ncredentials. However, the tester does not have access to the source code. Which of the following describes\nthe type of test being performed?","options":[["A","Partially known"],["B","Unknown"],["C","Known"],["D","Obfuscated"]],"correct":"A"},{"num":585,"text":"A security analyst learns that an attack vector, which was used as a part of a recent incident, was a wellknown IoT device exploit. The analyst needs to review logs to identify the time of initial exploit. Which of the\nfollowing logs should the analyst review first?","options":[["A","Wireless access point"],["B","Switch"],["C","Firewall"],["D","NAC"]],"correct":"C"},{"num":586,"text":"Which of the following best describes when a user installs an application from an unofficial application\nstore?","options":[["A","Side loading"],["B","Jailbreaking"],["C","Privilege escalation"],["D","Code signing"]],"correct":"A"},{"num":587,"text":"A security administrator must use a strategy to protect the company\u2019s data. The security administrator\ndecides to deploy FDE on the end user devices and TLS for all web connections. Which of the following\nconcepts are being used? (Choose two.)","options":[["A","Data segmentation"],["B","Data in transit"],["C","Data sovereignty"],["D","Data in use"],["E","Data at rest"],["F","Data redundancy"]],"correct":"BE"},{"num":588,"text":"An administrator investigating an incident is concerned about the downtime of a critical server due to a\nfailed drive. Which of the following would the administrator use to estimate the time needed to fix the issue?","options":[["A","MTTR"],["B","MTBF"],["C","RTO"],["D","RPO"]],"correct":"A"},{"num":589,"text":"A business manager is concerned about the availability of an application running on hardware in the local\ndata center. Which of the following solutions will improve availability while reducing maintenance overhead?","options":[["A","Deploy load balancing and HA."],["B","Transition from on premises to cloud."],["C","Purchase cybersecurity insurance."],["D","Decommission end-of-life hardware."]],"correct":"B"},{"num":590,"text":"A company wants to ensure that a mission-critical database can only be accessed from specific internal IP\naddresses. Which of the following should the company deploy to meet this requirement?","options":[["A","Web application firewall"],["B","Network tap"],["C","Intrusion prevention system"],["D","Jump server"]],"correct":"D"},{"num":591,"text":"A store is setting up wireless access for their employees. Management wants to limit the number of access\npoints while ensuring all areas of the store are covered. Which of the following tools will help management\ndetermine the number of access points needed?","options":[["A","Signal locator"],["B","WPA3"],["C","Heat map"],["D","Site survey"]],"correct":"D"},{"num":592,"text":"A security engineer has been assigned to work on a request from outside counsel. The security engineer\nmust provide all email correspondence within a specific date range. Which of the following actions should\nbe taken first in response to the request?","options":[["A","Send litigation hold notifications to identify affected data."],["B","Form a team to determine root cause analysis."],["C","Establish the chain of custody."],["D","Determine the type of preservation needed for evidence."]],"correct":"A"},{"num":593,"text":"A red-team provider tailgates into an organization's facility. Which of the following has occurred?","options":[["A","Insider threat"],["B","Brute-force attack"],["C","Physical penetration test"],["D","Active reconnaissance"]],"correct":"C"},{"num":594,"text":"Which of the following describes an agent-based application that detects and blocks malicious behavior on\nenterprise systems while disconnected from the corporate network?","options":[["A","Endpoint protection"],["B","System patching"],["C","HIDS"],["D","NGFW"]],"correct":"A"},{"num":595,"text":"A manager meets with various stakeholders involved with a recently resolved security incident. During the\nmeeting, they discuss potential improvements to the environment in order to better respond to future\nincidents. Which of the following incident response activities does this describe?","options":[["A","Recovery"],["B","Analysis"],["C","Lessons learned"],["D","Containment"]],"correct":"C"},{"num":596,"text":"A database engineer needs sample customer data for testing purposes. Which of the following techniques\ncan be used to remove sensitive information from database records while still providing sufficient data to\nperform testing?","options":[["A","Obfuscation"],["B","RBAC"],["C","Tokenization"],["D","Filtering"]],"correct":"A"},{"num":597,"text":"Which of the following encryption methods protects data if a user loses their laptop?","options":[["A","Volume"],["B","Full disk"],["C","Partition"],["D","File"]],"correct":"B"},{"num":598,"text":"A security analyst regularly receives emails from users who are concerned that attached files may be\nmalicious. Which of the following should the analyst use to evaluate the suspicious files and report back as\nto whether or not files are a threat?","options":[["A","Sanitization"],["B","Sandbox"],["C","Static analysis"],["D","Enumeration"]],"correct":"B"},{"num":599,"text":"Which of the following would be used to detect an employee who is emailing a customer list to a personal\naccount before leaving the company?","options":[["A","DLP"],["B","FIM"],["C","IDS"],["D","EDR"]],"correct":"A"},{"num":600,"text":"A CIRT team updates their playbooks to include instructions to respond to a ransomware attack. To prepare\nfor a real event, the team performs a simulation and assesses their performance afterward. Which of the\nfollowing activities does this describe?","options":[["A","Lessons learned"],["B","Root cause analysis"],["C","Disaster recovery planning"],["D","Tabletop exercise"]],"correct":"D"},{"num":601,"text":"Which of the following can automate vulnerability management?","options":[["A","CVE"],["B","SCAP"],["C","OSINT"],["D","CVSS"]],"correct":"B"},{"num":602,"text":"Which of the following is a reason to perform a one-time risk assessment?","options":[["A","Quantifying an annual loss expectancy"],["B","Updating the risk register periodically"],["C","Complying with a regulation"],["D","Decommissioning an application"]],"correct":"D"},{"num":603,"text":"An employee from the accounting department logs in to the website used for processing the company's\npayments. After logging in, a new desktop application automatically downloads on the employee's computer\nand causes the computer to restart. Which of the following attacks has occurred?","options":[["A","XSS"],["B","Watering hole"],["C","Typosquatting"],["D","Buffer overflow"]],"correct":"B"},{"num":604,"text":"An EDR solution recognizes that a specific workstation has outbound traffic to a malicious IP. Which of the\nfollowing would be the best action to take to contain the threat?","options":[["A","Change the passwords for all users accessing that workstation."],["B","Isolate the workstation as part of immediate response."],["C","Patch the workstation because it is likely vulnerable."],["D","Review the hardening and policies affecting that workstation."]],"correct":"B"},{"num":605,"text":"Which of the following would most likely prevent exploitation of an end-of-life, business-critical system?","options":[["A","Monitoring"],["B","Isolation"],["C","Decommissioning"],["D","Encryption"]],"correct":"B"},{"num":606,"text":"Which of the following is the most likely motivation for a hacktivist?","options":[["A","Financial gain"],["B","Service disruption"],["C","Philosophical beliefs"],["D","Corporate espionage"]],"correct":"C"},{"num":607,"text":"Which of the following is the best physical security control to prevent damage from a vehicle?","options":[["A","Security guard"],["B","Fencing"],["C","Lighting"],["D","Bollards"]],"correct":"D"},{"num":608,"text":"A security team wants to work with the same organization's development team to ensure WAF policies are\nautomatically created when applications are deployed. Which of the following concepts describes this\ncapability?","options":[["A","IaC"],["B","IoT"],["C","IoC"],["D","IaaS"]],"correct":"A"},{"num":609,"text":"Which of the following uses proprietary controls and is designed to function in harsh environments over\nmany years with limited remote access management?","options":[["A","ICS"],["B","Microservers"],["C","Containers"],["D","IoT"]],"correct":"A"},{"num":610,"text":"Which of the following data recovery strategies will result in a quick recovery at low cost?","options":[["A","Hot"],["B","Cold"],["C","Manual"],["D","Warm"]],"correct":"B"},{"num":611,"text":"An MSSP manages firewalls for hundreds of clients. Which of the following tools would be most helpful to\ncreate a standard configuration template in order to improve the efficiency of firewall changes?","options":[["A","SNMP"],["B","Benchmarks"],["C","Netflow"],["D","SCAP"]],"correct":"B"},{"num":612,"text":"After multiple phishing simulations, the Chief Security Officer announces a new program that incentivizes\nemployees to not click phishing links in the upcoming quarter. Which of the following security awareness\nexecution techniques does this represent?","options":[["A","Computer-based training"],["B","Insider threat awareness"],["C","SOAR playbook"],["D","Gamification"]],"correct":"D"},{"num":613,"text":"A security analyst sees an increase of vulnerabilities on workstations after a deployment of a company\ngroup policy. Which of the following vulnerability types will the analyst most likely find on the workstations?","options":[["A","Misconfiguration"],["B","Zero-day"],["C","Malicious update"],["D","Supply chain"]],"correct":"A"},{"num":614,"text":"Which of the following threat actors would most likely target an organization by using a logic bomb within an\ninternally-developed application?","options":[["A","Nation-state"],["B","Trusted insider"],["C","Organized crime group"],["D","Hacktivist"]],"correct":"B"},{"num":615,"text":"Which of the following is a company addressing when it rolls out MDM on all COPE devices?","options":[["A","Malware outbreaks"],["B","Phishing attacks"],["C","Unsupported applications"],["D","Data masking"]],"correct":"C"},{"num":616,"text":"An organization failed to account for the right-to-be-forgotten regulations. Which of the following impacts\nmight this action have on the company?","options":[["A","Fines"],["B","Data breaches"],["C","Revenue loss"],["D","Blackmail"]],"correct":"A"},{"num":617,"text":"A company is experiencing issues with employees leaving the company for a competitor and taking\ncustomer contact information with them. Which of the following tools will help prevent this from reoccurring?","options":[["A","FIM"],["B","NAC"],["C","IDS"],["D","UBA"]],"correct":"D"},{"num":618,"text":"A company that operates with most of its infrastructure in the cloud had its development environment\nbreached. The attackers gained access via a public-facing development application and were able to pivot\nto the production environment. Which of the following architecture changes would best prevent this from\noccurring again?","options":[["A","Moving each environment to a separate VPC in the company cloud account"],["B","Deploying firewalls in the company cloud account"],["C","Migrating the development environment to an on-premises environment"],["D","Implementing security groups restricting access between environments"]],"correct":"A"},{"num":619,"text":"Which of the following security concepts is being followed when applying encryption to sensitive data?","options":[["A","Confidentiality"],["B","Non-repudiation"],["C","Availability"],["D","Integrity"]],"correct":"A"},{"num":620,"text":"Which of the following cryptographic solutions would allow an organization to recover encrypted data after a\nkey becomes corrupted or is deleted?","options":[["A","Self-signed certificates"],["B","Escrow"],["C","Tokenization"],["D","Trusted Platform Module"]],"correct":"B"},{"num":621,"text":"An organization is evaluating the cost of licensing a new solution to prevent ransomware. Which of the\nfollowing is the most helpful in making this decision?","options":[["A","ALE"],["B","SLE"],["C","RTO"],["D","ARO"]],"correct":"A"},{"num":622,"text":"Which of the following should be used to ensure that a device is inaccessible to a network-connected\nresource?","options":[["A","Disablement of unused services"],["B","Web application firewall"],["C","Host isolation"],["D","Network-based IDS"]],"correct":"C"},{"num":623,"text":"During the investigation of a webmail log-in using compromised credentials, a security analyst needs to\nreview information about the source IP for the log-in. Which of the following logs should the analyst\nretrieve?","options":[["A","Network"],["B","Application"],["C","System"],["D","Firewall"]],"correct":"B"},{"num":624,"text":"Which of the following should be used to select a label for a file based on the file\u2019s value, sensitivity, or\napplicable regulations?","options":[["A","Verification"],["B","Certification"],["C","Classification"],["D","Inventory"]],"correct":"C"},{"num":625,"text":"A company makes a change during the appropriate change window, but the unsuccessful change extends\nbeyond the scheduled time and impacts customers. Which of the following would prevent this from\nreoccurring?","options":[["A","User notification"],["B","Change approval"],["C","Risk analysis"],["D","Backout plan"]],"correct":"D"},{"num":626,"text":"A security analyst is collecting evidence in response to an incident. Which of the following must the analyst\nmaintain in order to ensure the admissibility of the evidence in a court case?","options":[["A","Chain of custody"],["B","Legal hold"],["C","E-discovery"],["D","Tabletop exercise"]],"correct":"A"},{"num":627,"text":"Which of the following types of vulnerabilities involves attacking a system to access adjacent hosts?","options":[["A","VM escape"],["B","Side loading"],["C","Remote code execution"],["D","Resource exhaustion"]],"correct":"A"},{"num":628,"text":"While reviewing a recent compromise, a forensics team discovers that there are hard-coded credentials in\nthe database connection strings. Which of the following assessment types should be performed during\nsoftware development to prevent this from reoccurring?","options":[["A","Vulnerability scan"],["B","Penetration test"],["C","Static analysis"],["D","Quality assurance"]],"correct":"C"},{"num":629,"text":"Which of the following should be deployed on an externally facing web server in order to establish an\nencrypted connection?","options":[["A","Public key"],["B","Private key"],["C","Asymmetric key"],["D","Symmetric key"]],"correct":"A"},{"num":630,"text":"A security administrator receives multiple reports about the same suspicious email. Which of the following\nis the most likely reason for the malicious email\u2019s continued delivery?","options":[["A","Employees are flagging legitimate emails as spam."],["B","Information from reported emails is not being used to tune email filtering tools."],["C","Employees are using shadow IT solutions for email."],["D","Employees are forwarding personal emails to company email addresses."]],"correct":"B"},{"num":631,"text":"While browsing a web page, a user receives a pop-up with a link telling them to navigate to another site. To\nwhich of the following is the site vulnerable?","options":[["A","DoS"],["B","XSS"],["C","SQLi"],["D","TOC"]],"correct":"B"},{"num":632,"text":"An administrator must secure several end-of-life SCADA devices in a manufacturing facility on a limited\nbudget. Which of the following should the security administrator do to best secure these devices?","options":[["A","Segment the SCADA devices to their own subnet"],["B","Add the SCADA devices to a network monitoring tool"],["C","Apply security patches to the SCADA devices"],["D","Block internet access to the SCADA devices"]],"correct":"A"},{"num":633,"text":"A business is expanding to a new country and must protect customers from accidental disclosure of specific\nnational identity information. Which of the following should the security engineer update to best meet\nbusiness requirements?","options":[["A","SIEM"],["B","SCAP"],["C","DLP"],["D","WAF"]],"correct":"C"},{"num":634,"text":"Which of the following techniques would identify whether data has been modified in transit?","options":[["A","Hashing"],["B","Tokenization"],["C","Masking"],["D","Encryption"]],"correct":"A"},{"num":635,"text":"Which of the following strategies most effectively protects sensitive data at rest in a database?","options":[["A","Hashing"],["B","Masking"],["C","Tokenization"],["D","Obfuscation"]],"correct":"C"},{"num":636,"text":"Which of the following would an organization most likely use to minimize the loss of data on a file server in\nthe event that data needs to be restored due to loss of the primary server?","options":[["A","Monitoring"],["B","Journaling"],["C","Obfuscation"],["D","Tokenization"]],"correct":"B"},{"num":637,"text":"Which of the following would help reduce the impact of a zero-day vulnerability in NAS installed on a large\noffice network?","options":[["A","Encryption"],["B","Patching"],["C","Segmentation"],["D","Filtering"]],"correct":"C"},{"num":638,"text":"Which of the following should a security analyst use to prioritize the remediation of a vulnerability?","options":[["A","OSINT"],["B","CVE"],["C","IoC"],["D","CVSS"]],"correct":"D"},{"num":639,"text":"An IT team rolls out a new management application that uses a randomly generated MFA token that is sent\nto the administrator's phone. Despite this new MFA precaution, there is a security breach of the same\nsoftware. Which of the following describes this kind of attack?","options":[["A","Smishing"],["B","Typosquatting"],["C","Espionage"],["D","Pretexting"]],"correct":"A"},{"num":640,"text":"A security analyst reviews the following SIEM events:\n\nWhich of the following best describes the observed behavior?","options":[["A","Brute-force attack"],["B","Privilege escalation"],["C","Cross-site scripting"],["D","Password sharing"]],"correct":"D"},{"num":641,"text":"A company hired a security consultant to suggest a device that will protect its inbound HTTP traffic by\nimmediately blocking security violations. Which of the following should the consultant most likely suggest?","options":[["A","IPS"],["B","IDS"],["C","Proxy"],["D","WAF"]],"correct":"D"},{"num":642,"text":"A security manager needs an automated solution that will take immediate action to protect an organization\nagainst inbound malicious traffic. Which of the following is the best solution?","options":[["A","UEM"],["B","IPS"],["C","WAF"],["D","VPN"]],"correct":"B"},{"num":643,"text":"A Chief Security Officer wants to change user authentication to the company wireless network. The\nauthentication must use the LDAP database and must be centrally managed. Which of the following would\nhelp fulfill this requirement?","options":[["A","SAML"],["B","TACACS+"],["C","OAUTH"],["D","RADIUS"]],"correct":"D"},{"num":644,"text":"An administrator is creating domain profiles for each employee within the company. The administrator\nwants to make the process more efficient by assigning permissions based on user roles and departments.\nWhich of the following would most likely fulfill those requirements?","options":[["A","Resource provisioning"],["B","User provisioning"],["C","Security groups"],["D","Enforcing baselines"]],"correct":"C"},{"num":645,"text":"A systems administrator needs to update systems without disrupting operations. Which of the following\nshould the systems administrator and company leadership agree on?","options":[["A","Maintenance window"],["B","Backout plan"],["C","Standard operating procedure"],["D","Impact analysis"]],"correct":"A"},{"num":646,"text":"A company wants to improve the security of the local network by authenticating and encrypting all of the\ninternal traffic between corporate sites. Which of the following should the company deploy to achieve this\ngoal?","options":[["A","\u0415\u0410\u0420"],["B","IPSec"],["C","SD-WAN"],["D","WAF"]],"correct":"B"},{"num":647,"text":"A security analyst identifies an incident in the network. Which of the following incident response activities\nwould the security analyst perform next?","options":[["A","Containment"],["B","Detection"],["C","Eradication"],["D","Recovery"]],"correct":"A"},{"num":648,"text":"An administrator discovers a cross-site scripting vulnerability on a company website. Which of the following\nwill most likely remediate the issue?","options":[["A","Input validation"],["B","NGFW"],["C","Vulnerability scan"],["D","WAF"]],"correct":"A"},{"num":649,"text":"A service provider wants a cost-effective way to rapidly expand from providing internet links to managing\nthem. Which of the following methods will allow the service provider to best scale its services while\nmaintaining performance consistency?","options":[["A","Escalation support"],["B","Increased workforce"],["C","Baseline enforcement"],["D","Technical debt"]],"correct":"C"},{"num":650,"text":"Which of the following control types describes an alert from a SIEM tool?","options":[["A","Preventive"],["B","Corrective"],["C","Compensating"],["D","Detective"]],"correct":"D"},{"num":651,"text":"Which of the following attacks primarily targets insecure networks?","options":[["A","Evil twin"],["B","Impersonation"],["C","Watering hole"],["D","Pretexting"]],"correct":"A"},{"num":652,"text":"A penetration testing report indicated that an organization should implement controls related to database\ninput validation. Which of the following best identifies the type of vulnerability that was likely discovered\nduring the test?","options":[["A","XSS"],["B","Command injection"],["C","Buffer overflow"],["D","SQLi"]],"correct":"D"},{"num":653,"text":"Which of the following activities would involve members of the incident response team and other\nstakeholders simulating an event?","options":[["A","Lessons learned"],["B","Digital forensics"],["C","Tabletop exercise"],["D","Root cause analysis"]],"correct":"C"},{"num":654,"text":"Which of the following data classifications best applies when data is intended for internal organizational use\nor with commercial partners?","options":[["A","Public"],["B","Restricted"],["C","Confidential"],["D","Sensitive"]],"correct":"C"},{"num":655,"text":"Which of the following technologies can achieve microsegmentation?","options":[["A","Next-generation firewalls"],["B","Software-defined networking"],["C","Embedded systems"],["D","Air-gapped"]],"correct":"B"},{"num":656,"text":"Which of the following metrics impacts the backup schedule as part of the BIA?","options":[["A","RTO"],["B","RPO"],["C","MTTR"],["D","MTBF"]],"correct":"B"},{"num":657,"text":"A customer reports that software the customer downloaded from a public website has malware in it.\nHowever, the company that created the software denies any malware in its software at delivery time. Which\nof the following techniques will address this concern?","options":[["A","Secure storage"],["B","Static code analysis"],["C","Input validation"],["D","Code signing"]],"correct":"D"},{"num":658,"text":"After completing an annual external penetration test, a company receives the following guidance:\nDecommission two unused web servers currently exposed to the internet.\nClose 18 open and unused ports found on their existing production web servers.\nRemove company email addresses and contact info from public domain registration records.\nWhich of the following security practices best describes these recommendations?","options":[["A","Attack surface reduction"],["B","Vulnerability assessment"],["C","Tabletop exercise"],["D","Business impact analysis"]],"correct":"A"},{"num":659,"text":"Which of the following receives logs from various devices and services, and then presents alerts?","options":[["A","SIEM"],["B","SCADA"],["C","SNMP"],["D","SCAP"]],"correct":"A"},{"num":660,"text":"A security analyst investigates logs and notices similar data types are being sent to IP addresses with a bad\nreputation. Which of the following attack types does this best describe?","options":[["A","Logic bomb"],["B","Worm"],["C","Spyware"],["D","Keylogger"]],"correct":"C"},{"num":661,"text":"Which of the following describes a situation where a user is authorized before being authenticated?","options":[["A","Privilege escalation"],["B","Race condition"],["C","Tailgating"],["D","Impersonation"]],"correct":"A"},{"num":662,"text":"An employee decides to take malicious action against an organization after being passed over for a\npromotion. Which of the following threats does the employee now represent?","options":[["A","Insider threat"],["B","Nation-state"],["C","Shadow IT"],["D","Hacktivist"]],"correct":"A"},{"num":663,"text":"At the start of a penetration test, the tester checks OSINT resources for information about the client\nenvironment. Which of the following types of reconnaissance is the tester performing?","options":[["A","Active"],["B","Passive"],["C","Offensive"],["D","Defensive"]],"correct":"B"},{"num":664,"text":"An administrator is estimating the cost associated with an attack that could result in the replacement of a\nphysical server. Which of the following processes is the administrator performing?","options":[["A","Quantitative risk analysis"],["B","Disaster recovery test"],["C","Physical security controls"],["D","Threat modeling"]],"correct":"A"},{"num":665,"text":"A user's system became infected when malware was downloaded and extracted. The malware is now\nactive in the computer's volatile storage. Which of the following best describes the technique leveraged by\nthe malware?","options":[["A","Race condition"],["B","Zero-day exploit"],["C","Buffer overflow"],["D","Memory injection"]],"correct":"D"},{"num":666,"text":"An attacker gained access to a virtual machine and was able to access the hypervisor. Which of the\nfollowing describes this attack?","options":[["A","VM escape"],["B","SQL injection"],["C","Privilege escalation"],["D","Logic bomb"]],"correct":"A"},{"num":667,"text":"An administrator learns that users are receiving large quantities of unsolicited messages. The administrator\nchecks the content filter and sees hundreds of messages sent to multiple users. Which of the following best\ndescribes this kind of attack?","options":[["A","Watering hole"],["B","Typosquatting"],["C","Business email compromise"],["D","Phishing"]],"correct":"D"},{"num":668,"text":"Which of the following can assist in recovering data if the decryption key is lost?","options":[["A","CSR"],["B","Salting"],["C","Root of trust"],["D","Escrow"]],"correct":"D"},{"num":669,"text":"A company's antivirus solution is effective in blocking malware but often has false positives. The security\nteam has spent a significant amount of time on investigations but cannot determine a root cause. The\ncompany is looking for a heuristic solution. Which of the following should replace the antivirus solution?","options":[["A","SIEM"],["B","EDR"],["C","DLP"],["D","IDS"]],"correct":"B"},{"num":670,"text":"Attackers created a new domain name that looks similar to a popular file-sharing website. Which of the\nfollowing threat vectors is being used?","options":[["A","Watering-hole attack"],["B","Brand impersonation"],["C","Phishing"],["D","Typosquatting"]],"correct":"D"},{"num":671,"text":"Which of the following teams combines both offensive and defensive testing techniques to protect an\norganization's critical systems?","options":[["A","Red"],["B","Blue"],["C","Purple"],["D","Yellow"]],"correct":"C"},{"num":672,"text":"Which of the following best describes the practice of researching laws and regulations related to information\nsecurity operations within a specific industry?","options":[["A","Compliance reporting"],["B","GDPR"],["C","Due diligence"],["D","Attestation"]],"correct":"C"},{"num":673,"text":"Which of the following should a technician perform to verify the integrity of a file transferred from one device\nto another?","options":[["A","Authentication"],["B","Obfuscation"],["C","Hashing"],["D","Encryption"]],"correct":"C"},{"num":674,"text":"During an investigation, a security analyst discovers traffic going out to a command-and-control server. The\nanalyst must find out if any data exfiltration has occurred. Which of the following would best help the analyst\ndetermine this?","options":[["A","Application log"],["B","Metadata"],["C","Network log"],["D","Packet capture"]],"correct":"D"},{"num":675,"text":"A security analyst is investigating an alert that was produced by endpoint protection software. The analyst\ndetermines this event was a false positive triggered by an employee who attempted to download a file.\nWhich of the following is the most likely reason the download was blocked?","options":[["A","A misconfiguration in the endpoint protection software"],["B","A zero-day vulnerability in the file"],["C","A supply chain attack on the endpoint protection vendor"],["D","Incorrect file permissions"]],"correct":"A"},{"num":676,"text":"A company discovers that an employee was paid by a competitor to save internal business files to a thumb\ndrive and deliver it to the competitor. Which of the following is most likely the employee's motivation?","options":[["A","Revenge"],["B","Financial gain"],["C","Blackmail"],["D","Data exfiltration"]],"correct":"B"},{"num":677,"text":"Which of the following outlines the configuration, maintenance, and security roles between a cloud service\nprovider and the customer?","options":[["A","Service-level agreement"],["B","Responsibility matrix"],["C","Memorandum of understanding"],["D","Non-disclosure agreement"]],"correct":"B"},{"num":678,"text":"An attacker used XSS to compromise a web server. Which of the following solutions could have been used\nto prevent this attack?","options":[["A","NGFW"],["B","UTM"],["C","WAF"],["D","NAC"]],"correct":"C"},{"num":680,"text":"Which of the following non-production sites is an operational mirror of the primary data center and is ready\nfor use if the primary data center experiences an outage?","options":[["A","Hot"],["B","Warm"],["C","Cold"],["D","Frozen"]],"correct":"A"},{"num":681,"text":"Which of the following will harden access to a new database system? (Choose two.)","options":[["A","Jump server"],["B","NIDS"],["C","Monitoring"],["D","Proxy server"],["E","Host-based firewall"],["F","WAF"]],"correct":"AE"},{"num":682,"text":"A few weeks after deploying additional email servers, a company begins to receive complaints from\nemployees that messages they send are going into their recipients' spam folders. Which of the following\nneeds to be updated in order to resolve this issue?","options":[["A","CNAME"],["B","SMTP"],["C","DLP"],["D","SPF"]],"correct":"D"},{"num":683,"text":"A company uses a cloud-based platform for file storage and wants to ensure the security of its data in\ntransit. Which of the following should the company verify are in place to secure this type of communication?\n(Choose two.)","options":[["A","TLS certificates"],["B","WPA2 encryption"],["C","HTTPS"],["D","Virtual private network"],["E","Encryption key management"],["F","Digital signatures"]],"correct":"AC"}];
export default QUESTIONS;
